'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('solder','Solder comes through Middle English and Old French from Latin solidare, “to make solid”; the verb joins metal with a melted filler that has a lower melting point than the pieces.',C('solder.s1','金工','The technician soldered a new wire to the circuit board without melting the board itself.','技术员把一根新导线焊到电路板上，没有熔化板子本身。','solder A to B; solder a joint; soldering iron','及物动词，接合金属时熔化填料金属而不熔化工件。','the filler bonds the wire to the board.','金工'),M('She soldered the two copper pipes by melting both pipes completely into a puddle.','She soldered the copper pipes by melting filler metal into the joint while keeping the pipes intact.','焊料熔化并连接金属，工件本身通常不熔化。','meaning'),[Q(1,'What did the technician melt to make the joint?','A lower-melting filler metal','The entire circuit board','The insulation on every wire','Soldering melts filler, not the joined pieces.','meaning'),Q(1,'Why could the board remain intact?','The filler melts at a lower temperature than the parts.','Solder means to dissolve a board in water.','The wire was only tied on with string.','The filler forms the bond without melting the components.','context'),Q(1,'Which instruction uses solder as a verb?','Solder the wire to the contact.','Solder the contact into a liquid soup.','Solder at the wire with a hammer.','Solder can take the joined objects and the joining relation.','grammar'),Q(1,'Solder is historically connected with a Latin verb meaning…','make solid','make sound','make solitary','The Latin source solidare meant to make solid.','word-formation')]);
P('soldier','Soldier entered English through Old French soudier, originally a person serving for pay, from Medieval Latin solidarius related to solidus, a coin.',C('soldier.s1','军事','The soldier carried supplies to the unit stationed beyond the ridge.','这名士兵把补给送到山脊另一侧驻扎的部队。','a soldier in the army; serve as a soldier','名词，尤指军队中非军官的成员。','member of an army below officer rank.','军事'),M('The soldier joined the army but was appointed its commanding general on the first day.','The soldier joined the army as an enlisted member of the unit.','词条基本义项是军人，尤其非军官；将军是军官。','distinction'),[Q(1,'In the source sense, a soldier is…','a member of an army, especially below officer rank','a civilian who sells uniforms','the commander of every army','The entry identifies an army member, especially a non-officer.','meaning'),Q(1,'Who is described as the soldier in the sentence?','The unit member carrying supplies','A doctor treating patients at a clinic','A lawyer preparing a contract','The context places the person in an army unit.','context'),Q(1,'Which phrase is natural?','serve as a soldier','serve soldierly as a','soldier into the army at','As introduces the role after serve.','grammar'),Q(1,'The older word behind soldier referred to service…','for pay','in a choir','on a farm','The French/Latin history relates to paid service.','word-formation')]);
P('soldiers','Soldiers is the regular plural of soldier, whose English history goes through Old French soudier and Medieval Latin solidarius, a paid servant or soldier.',C('soldiers.s1','军事','The soldiers checked the bridge before the convoy crossed it.','士兵们在车队过桥前检查了桥梁。','soldiers in a unit; a group of soldiers','复数名词，指在军队服役的士兵。','multiple army members perform the check.','军事'),M('The soldiers checked the bridge, but one soldier were assigned to each side.','The soldiers checked the bridge, and one soldier was assigned to each side.','复数主语soldiers需搭配were；改成单数one soldier才用was。','grammar'),[Q(1,'Soldiers are…','people who serve in an army below officer rank','a type of bridge inspection','one person serving as a lawyer','The plural retains soldier’s army-member sense.','meaning'),Q(1,'How many soldiers checked the bridge?','More than one','Exactly none','Only one, as stated by the plural','The plural noun refers to multiple army members.','context'),Q(1,'Choose the correct sentence.','The soldiers were ready.','The soldiers was ready.','A soldiers were ready.','Plural soldiers takes were and no article a.','grammar'),Q(1,'Soldiers is the plural of…','soldier','solid','solitude','The noun takes regular plural -s.','word-formation')]);
P('sole','Sole comes from Latin solus, “alone, only”; the foot/shoe and fish senses have separate histories.',[C('sole.s1','选择','Mara was the sole witness to the late-night delivery.','玛拉是深夜送货一事唯一的目击者。','the sole reason/person/witness; sole + noun','形容词，表示唯一的、仅有的。','no other witness is mentioned.','选择'),C('sole.s2','法律','The contract gave the designer sole ownership of the original drawings.','合同赋予设计师对原始图纸的独占所有权。','sole ownership/control; sole right to + verb','形容词，也表示某人或某团体独占、专有。','ownership belongs only to designer.','法律'),C('sole.s3','身体','A small stone was stuck to the sole of his hiking boot.','一块小石子粘在他的登山靴鞋底上。','the sole of the foot/shoe; shoe sole','名词，指脚掌底部或鞋底。','stone touches bottom of boot.','身体'),C('sole.s4','饮食','The restaurant served grilled sole with a lemon sauce.','餐厅供应配柠檬酱的烤鳎鱼。','Dover sole; fillet of sole','名词，指一种可食用的扁形海鱼。','fish is the menu dish.','饮食')],M('The sole witness was one of twelve people who all saw the delivery.','The sole witness was the only person who saw the delivery.','sole表示唯一，不能同时说有十二名同样的目击者。','meaning'),[Q(1,'The sole witness was…','the only witness','one of many witnesses','the witness’s shoe bottom','Sole sense 1 means only.','meaning'),Q(2,'Sole ownership means the drawings…','belong exclusively to one owner','are jointly owned by everyone','are drawn on leather shoe bottoms','Sole sense 2 means exclusive ownership.','context'),Q(3,'The sole of a boot is…','its bottom surface','its lace','a flat fish','Sole also names the bottom of a shoe.','meaning'),Q(4,'Which dish could be grilled sole?','A flat sea fish served as food','The only witness at a trial','The bottom of a shoe','Sole has a separate fish sense.','meaning')]);
P('solely','Solely is formed from sole + -ly and means only or exclusively, with no other person, cause, or factor involved.',C('solely.s1','原因','The delay was caused solely by a power failure at the station.','延误完全是由车站停电造成的。','solely because of; depend solely on; solely responsible','副词，表示唯一地、仅仅由某因素造成或依赖某事。','one cause is identified.','原因'),M('The delay was caused solely by a power failure and also by three unrelated events.','The delay was caused solely by the power failure.','solely排除其他原因。','meaning'),[Q(1,'If a delay was caused solely by a power failure, it was caused…','only by that failure','by the failure and many other factors','by no event at all','Solely excludes other causes.','meaning'),Q(1,'Which phrase matches the source sense?','depend solely on one record','depend solely and also on four other records','depend sole for records','Solely means exclusively.','context'),Q(1,'Which sentence uses solely as an adverb?','The grant is funded solely by donations.','The sole grant funded donationsly.','The grant is solely fund by donation.','Solely modifies the source of funding.','grammar'),Q(1,'Solely is built from sole plus…','-ly','-er','-ship','The suffix -ly forms the adverb.','word-formation')]);
P('solemn','Solemn comes from Latin sollemnis, “appointed or celebrated at a stated time,” later describing formal, serious occasions and expressions.',[C('solemn.s1','仪式','The judge took a solemn oath before beginning the hearing.','法官在开始听证会前庄严宣誓。','a solemn promise/oath/ceremony; solemn occasion','形容词，指仪式、承诺等正式而严肃，常带有庄重意味。','formal oath at official event.','仪式'),C('solemn.s2','表情','The child wore a solemn expression while listening to the announcement.','孩子听公告时神情严肃。','a solemn face/look; look solemn','形容词，也形容严肃、不带笑容的神情。','expression is serious.','表情')],M('The judge made a solemn oath as a joke, laughing throughout the formal ceremony.','The judge made a solemn oath in a serious and respectful manner.','庄严誓言与全程嬉笑的态度不相符。','meaning'),[Q(1,'A solemn oath is made…','formally and seriously','as a casual joke','while refusing to make any promise','Solemn sense 1 describes a grave formal promise.','meaning'),Q(2,'A solemn expression looks…','serious and unsmiling','excited and laughing','confused by a loud sound','Sense 2 concerns facial appearance.','context'),Q(1,'Which collocation is natural?','a solemn ceremony','a solemnly ceremony','solemn ceremonying','Solemn is an adjective modifying ceremony.','grammar'),Q(1,'Solemn originally related to an event…','appointed or held at a stated time','that happens every second','with no people present','The Latin history referred to a fixed observance.','word-formation')]);
P('solemnity','Solemnity is formed from solemn + -ity; it names the serious, formal quality or atmosphere of a ceremony or manner.',C('solemnity.s1','仪式','The quiet solemnity of the memorial service moved even the visitors who had not known the family.','追思仪式安静庄严的气氛甚至打动了不认识逝者家人的来宾。','the solemnity of a ceremony; with solemnity','名词，指庄严、肃穆的态度或氛围。','formal quiet atmosphere is moving.','仪式'),M('The solemnity of the memorial was obvious from the clown costumes, loud jokes, and dancing.','The solemnity of the memorial was clear from the quiet and respectful behavior.','喧闹玩笑与肃穆氛围相反。','meaning'),[Q(1,'The solemnity of a memorial is its…','serious and respectful atmosphere','bright colour scheme','length in kilometres','Solemnity names a grave, formal quality.','meaning'),Q(1,'What created solemnity at the service?','Quiet and respectful behavior','Loud jokes and clown costumes','A recipe for soup','The context links solemnity with a respectful memorial.','context'),Q(1,'Which phrase is natural?','the solemnity of the service','the solemnity service ofly','a solemnly of service','Of links the quality to the event.','grammar'),Q(1,'Solemnity is formed from solemn with…','-ity','-less','-ish','The suffix -ity forms an abstract noun.','word-formation')]);
P('solemnly','Solemnly is the adverb formed from solemn + -ly; it describes acting with deep seriousness, especially in a ceremony or promise.',C('solemnly.s1','仪式','The mayor solemnly promised that the damaged playground would be rebuilt.','市长郑重承诺将重建受损的游乐场。','solemnly promise/declare/swear; speak solemnly','副词，表示郑重严肃地，常修饰承诺或正式宣告。','promise given with gravity.','仪式'),M('The mayor solemnly promised to rebuild the playground while joking that the promise meant nothing.','The mayor solemnly promised to rebuild the playground and treated the commitment seriously.','若承诺被当作玩笑且毫无分量，就不算郑重承诺。','meaning'),[Q(1,'To promise solemnly is to promise…','with serious commitment','without intending to keep the promise','in a silly song','Solemnly signals gravity and seriousness.','meaning'),Q(1,'What did the mayor do solemnly?','Promised to rebuild the playground','Drew a sketch of a shoe','Refused to speak at all','The sentence describes a serious public promise.','context'),Q(1,'Which sentence uses solemnly correctly?','She solemnly swore to tell the truth.','She made a solemnly oath.','She solemn promised the truth.','Solemnly modifies the verb swore.','grammar'),Q(1,'Solemnly adds which suffix to solemn?','-ly','-ity','-er','-ly forms the adverb.','word-formation')]);
P('solicit','Solicit comes from Latin sollicitare, “stir up, trouble, urge”; English uses it for formally seeking money, help, or support, and in a separate legal sense for offering sex for payment in public.',[C('solicit.s1','筹款','The shelter will solicit donations from local businesses before winter.','避难所将在冬季前向当地企业募集捐款。','solicit donations/support; solicit someone for help','动词，指主动请求或招揽金钱、帮助、支持。','organization asks businesses for donations.','筹款'),C('solicit.s2','法律','Police warned vendors not to solicit customers for sex near the station.','警方警告性工作者不要在车站附近公开拉客。','solicit for prostitution; solicit customers','动词的法律语境义，指在公共场所招揽性交易。','public solicitation for sex.','法律')],M('The charity solicited donations by refusing to ask anyone for money or support.','The charity solicited donations by asking local businesses to contribute.','solicit donations意味着主动征求捐赠。','meaning'),[Q(1,'A charity that solicits donations…','asks people or businesses to contribute','hides every request for support','sells donations back to the donor','The first sense is to seek contributions.','meaning'),Q(2,'In the legal warning, vendors were told not to…','publicly offer sex for payment','donate money to a shelter','solicit a music solo','This is the distinct public solicitation sense.','context'),Q(1,'Which phrase fits the fundraising sense?','solicit support from residents','solicit residents into a solemn oath','solicit of support residents','From introduces the people asked.','grammar'),Q(1,'The Latin source sollicitare could mean…','urge or stir up','melt metal','sing alone','The English verb developed from a Latin verb of urging or troubling.','word-formation')]);
P('solicitor','Solicitor comes from solicit + -or through Anglo-French legal usage; in British law it is a lawyer who advises clients and prepares legal documents.',C('solicitor.s1','法律','A solicitor reviewed the lease and explained the tenant’s obligations before it was signed.','一名事务律师在租约签署前审阅了合同，并解释了租户的义务。','consult a solicitor; solicitor for a client','名词，尤指英国负责法律咨询、文件准备等工作的律师。','lawyer reviews lease and advises client.','法律'),M('The solicitor advised the tenant, although she had no legal training and was hired only to repair the roof.','The solicitor advised the tenant as a qualified legal professional.','事务律师从事法律咨询，不是修屋顶的工人。','meaning'),[Q(1,'A British solicitor commonly…','gives legal advice and prepares legal papers','repairs roofs for tenants','serves as a court jury','That is the dictionary sense.','meaning'),Q(1,'What did the solicitor do before signing?','Reviewed the lease and explained duties','Replaced the roof tiles','Sang a solo at the hearing','The example shows legal review and advice.','context'),Q(1,'Which phrase is natural?','consult a solicitor about the lease','consult a solicitor the lease aboutly','consult to solicitor about lease','Consult a solicitor is the standard construction.','grammar'),Q(1,'Solicitor is related in form to the verb…','solicit','sole','solidify','The noun names a person associated with soliciting or legal practice.','word-formation')]);
P('solicitous','Solicitous comes from Latin sollicitus, “anxious, troubled,” and describes attentive concern for another person’s health or comfort.',C('solicitous.s1','关怀','The nurse was solicitous about the patient’s comfort and checked whether the room was warm enough.','护士很关心病人的舒适度，还查看房间是否够暖和。','solicitous of/about someone; solicitous attention','形容词，表示体贴关切、细心照料。','nurse checks patient’s comfort.','关怀'),M('The nurse was solicitous about the patient’s comfort, ignoring every request for water and warmth.','The nurse was solicitous about the patient’s comfort and responded carefully to requests.','漠视需求不是细心关照。','meaning'),[Q(1,'A solicitous nurse shows…','careful concern for a patient’s comfort','indifference to every request','a wish to sell medicine','Solicitous means attentive and concerned.','meaning'),Q(1,'What showed the nurse was solicitous?','She checked that the room was warm enough.','She refused to check the room.','She left without speaking.','The detail demonstrates attention to comfort.','context'),Q(1,'Which phrase is natural?','solicitous about her health','solicitous her healthly about','solicitous to health ofly','About can introduce the concern.','grammar'),Q(1,'Solicitous is historically linked to a Latin word meaning…','anxious or troubled','metallic and hard','only one','The adjective developed from Latin sollicitus.','word-formation')]);
P('solid','Solid comes from Latin solidus, “firm, whole”; it describes matter that is not liquid or gas, objects that are not hollow, dependable evidence, or the material itself.',[C('solid.s1','物理','At room temperature, wax is solid rather than liquid, though heat can melt it.','在室温下，蜡是固体而不是液体，但加热可以使它融化。','solid, liquid, or gas; solid at room temperature','形容词，指固态的、非液体也非气体的。','wax is in solid state.','物理'),C('solid.s2','结构','The carpenter chose a solid oak door with no hollow core.','木匠选了一扇实心橡木门，没有中空门芯。','solid wood/door; solid evidence/support','形容词，也指实心、坚固，或可靠扎实。','door is not hollow.','建筑'),C('solid.s3','化学','The chemist separated the solid from the liquid by filtering the mixture.','化学家通过过滤混合物把固体与液体分离。','a solid; solids and liquids','名词，指固体物质。','material is the solid phase.','化学')],M('The wax was solid at room temperature, flowing freely like water without being heated.','The wax was solid at room temperature and flowed only after it was heated.','固态蜡不会像水一样自由流动。','meaning'),[Q(1,'A solid substance is…','in a firm state rather than liquid or gas','always a gas','a hollow space','Solid sense 1 concerns physical state.','meaning'),Q(2,'A solid oak door with no hollow core is…','made of firm material throughout','filled with liquid wax','a paper-thin drawing','Sense 2 means not hollow.','context'),Q(3,'In a lab, a solid is…','a substance in the solid state','a reliable witness only','a musical performance','Solid is also a count noun for solid matter.','meaning'),Q(1,'Which phrase is natural for evidence?','solid evidence','solidly evidence','evidence solidnessly','Solid can mean reliable or convincing.','collocation')]);
P('solidarity','Solidarity derives from French solidarité, related to Latin solidus, “whole, firm”; it is unity and mutual support within or for a group.',[C('solidarity.s1','团体','The nurses showed solidarity by sharing shifts when a colleague became ill.','一名同事生病时，护士们通过互相顶班表达团结。','show/express solidarity; solidarity among workers','名词，指群体成员之间的团结和互助。','colleagues support one another.','团体'),C('solidarity.s2','声援','Thousands gathered in solidarity with families displaced by the flood.','数千人聚集起来，声援因洪水流离失所的家庭。','in solidarity with + group/person','名词，也指对处境困难的人或群体公开表示支持。','crowd supports affected families.','声援')],M('The team showed solidarity by refusing to help the injured colleague and leaving her alone.','The team showed solidarity by covering the injured colleague’s shift and supporting her.','互助支持与拒绝帮助相矛盾。','meaning'),[Q(1,'Solidarity among coworkers is…','a sense of unity and mutual support','competition to leave others unsupported','a solid chemical state','The first sense is unity within a group.','meaning'),Q(2,'A crowd in solidarity with flood victims…','publicly supports the affected families','opposes every family’s recovery','is measuring the river depth','In solidarity with names the group receiving support.','context'),Q(1,'Which construction is standard?','in solidarity with the families','solidarity to the families inly','solidarity the families with on','The phrase is in solidarity with.','grammar'),Q(1,'The word solidarity is related to Latin…','solidus, meaning whole or firm','sonus, meaning sound','solus, meaning alone','Its word history is connected with the idea of a whole.','word-formation')]);
P('solidification','Solidification is formed from solidify + -cation; it names the process by which a liquid or soft material becomes solid.',C('solidification.s1','物理','The solidification of the candle wax began as soon as the flame was extinguished.','蜡烛火焰熄灭后，蜡立即开始凝固。','solidification of a liquid; cooling and solidification','名词，指液体冷却或凝结成固体的过程。','liquid wax becomes solid as it cools.','物理'),M('The solidification of the wax turned it from a hard block into a flowing liquid.','The solidification of the wax turned the liquid into a firm block.','固化是从液态变固态，而非相反。','meaning'),[Q(1,'Solidification is the process of…','a material becoming solid','a solid block melting into gas','a group showing unity','The suffixal noun names the change into a solid.','meaning'),Q(1,'What happened after the candle went out?','The wax began to solidify as it cooled.','The wax became hotter and more fluid.','The candle turned into a metal wire.','Cooling led to solidification.','context'),Q(1,'Which phrase is natural?','the solidification of molten wax','the solidify of molten wax','solidification moltenly of wax','Of introduces the material that becomes solid.','grammar'),Q(1,'Solidification is formed from the verb…','solidify','solicit','solemnize','Solidify is the corresponding verb.','word-formation')]);
P('solidify','Solidify combines solid + -ify, meaning make or become solid; figuratively it means make a plan, position, or relationship firmer.',[C('solidify.s1','物理','Leave the melted chocolate at room temperature so that it can solidify before you cut it.','把融化的巧克力放在室温下，让它凝固后再切。','solidify as it cools; solidify into a block','动词，指冷却后变硬、凝固，也可表示使其凝固。','melted chocolate hardens.','物理'),C('solidify.s2','计划','The committee added a delivery date to solidify its agreement with the supplier.','委员会补上交货日期，以巩固与供应商的协议。','solidify a plan/agreement; solidify support','动词也可指使计划、立场或支持更稳固明确。','specific date makes agreement firmer.','计划')],M('The committee added a delivery date to solidify its agreement, making the terms less definite.','The committee added a delivery date to solidify its agreement and make the terms firmer.','巩固协议会让条款更明确，而非更含糊。','meaning'),[Q(1,'Chocolate solidifies when it…','cools and becomes firm','is heated until it melts','is divided into a group','Sense 1 is a physical change to solid.','meaning'),Q(2,'Adding a date can solidify an agreement by…','making its terms more definite','turning paper into chocolate','removing every commitment','The figurative sense means make firmer.','context'),Q(1,'Which phrase uses the figurative sense?','solidify support for the proposal','solidify the melted wax as it cools','solidify the ice into water','Support is made firmer in the figurative use.','meaning'),Q(1,'The suffix -ify commonly means…','make or become','person who does','state of being without','Solidify means make or become solid.','word-formation')]);
P('solidity','Solidity is from solid + -ity; it means physical firmness or the dependable strength of reasoning, evidence, or an institution.',[C('solidity.s1','结构','The solidity of the bridge was confirmed by engineers before it reopened.','工程师确认桥梁结构牢固后，它才重新开放。','test/check the solidity of a structure','名词，指物体结构的坚实、牢固程度。','inspection confirms firmness.','结构'),C('solidity.s1','论证','Readers questioned the solidity of the report because its figures came from an unverified source.','读者质疑报告论证是否可靠，因为数字来自未经核实的来源。','the solidity of an argument/evidence','名词也指论点、证据或制度的可靠扎实。','source is unverified.','论证')],M('The solidity of the report was unquestionable even though every figure was invented and unverified.','The report lacked solidity because its figures were invented and unverified.','虚构且未经核实的数据削弱论证的可靠性。','meaning'),[Q(1,'The solidity of a bridge concerns its…','physical firmness and strength','colour and decoration','number of passengers','Sense 1 is structural firmness.','meaning'),Q(1,'Questioning a report’s solidity means questioning its…','reliability and strength of evidence','paper thickness','publication date only','The figurative use means dependability.','context'),Q(1,'Which phrase is natural?','the solidity of the evidence','the solid of the evidenceity','the solidity evidence by','Of connects solidity to what is being assessed.','grammar'),Q(1,'Solidity is formed from solid plus…','-ity','-ly','-ize','The suffix creates an abstract noun for a quality.','word-formation')]);
P('solidly','Solidly is formed from solid + -ly; it means firmly and reliably, and can describe a large unified majority or support.',[C('solidly.s1','结构','The shelves were fixed solidly to the wall and held the heavy books without bending.','书架牢牢固定在墙上，承放厚重书籍也没有弯曲。','fixed/built solidly; stand solidly','副词，表示牢固、可靠地。','secure attachment holds weight.','结构'),C('solidly.s1','投票','The proposal was solidly supported by every neighborhood represented at the meeting.','会上每个社区的代表都坚决支持这项提案。','solidly behind/in support of; solidly vote for','副词也表示广泛一致、坚定地支持。','all groups support proposal.','投票')],M('The shelves were fixed solidly to the wall, but they fell at the lightest touch because the screws were loose.','The shelves were fixed solidly with secure screws and stayed in place under the books.','松动螺钉会让书架不牢固。','meaning'),[Q(1,'Shelves fixed solidly are fixed…','firmly and securely','loosely and temporarily','only by a vote','The first sense is physical firmness.','meaning'),Q(1,'A proposal solidly supported by every neighborhood has…','broad and united support','no supporters at all','support only from one unknown person','The second use signals strong group backing.','context'),Q(1,'Which phrase is natural?','the shelves are solidly attached','the shelves are solid attachmently','solidly the attached shelves arely','The adverb modifies attached.','grammar'),Q(1,'Solidly is made from solid plus…','-ly','-ity','-ment','The suffix forms an adverb.','word-formation')]);
P('solitary','Solitary comes from Latin solitarius, from solus “alone”; it describes something done alone, a single isolated thing, or someone who prefers living alone.',[C('solitary.s1','活动','She took a solitary walk along the coast before the town woke up.','镇上苏醒前，她独自在海边散步。','a solitary walk/trip; live a solitary life','形容词，指独自进行、没有同伴参加。','walk is taken alone.','活动'),C('solitary.s2','数量','A solitary lamp remained lit in the empty station.','空荡荡的车站里只有一盏灯还亮着。','a solitary tree/figure; a solitary + singular noun','形容词，也表示孤零零的、唯一的一个。','one lamp alone in station.','数量'),C('solitary.s3','性格','The novelist was a solitary who preferred a quiet cabin to crowded cafés.','这位小说家喜欢独处，比起拥挤的咖啡馆更爱安静的小木屋。','a solitary; solitary by nature','名词可指喜欢独处或独居的人。','person prefers being alone.','性格')],M('She took a solitary walk with a group of thirty friends beside her.','She took a solitary walk alone along the coast.','有一群同行者就不是独自散步。','meaning'),[Q(1,'A solitary walk is…','taken alone','taken by a crowd','a group vote','Sense 1 means done alone.','meaning'),Q(2,'A solitary lamp in an empty station is…','the only lamp there','one lamp among hundreds','a soundproof room','Solitary can mean single or isolated.','context'),Q(3,'A solitary may be…','a person who prefers being alone','a person who repairs lamps','a singer in a choir','The noun sense names someone living apart from others.','meaning'),Q(1,'Which phrase is natural?','a solitary tree on the hill','a solitarily tree on hill','a tree solitarying there','Solitary is an adjective before tree.','grammar')]);
P('solitude','Solitude comes from Latin solitudo, from solus “alone”; it is the state of being alone and can refer to peaceful privacy or painful isolation.',[C('solitude.s1','休闲','After a week of meetings, Ren went to the cabin to enjoy a few days of solitude.','开了一周会议后，任去小木屋享受几天独处时光。','enjoy/seek solitude; a moment of solitude','名词，指周围没有他人的独处状态。','chooses time alone for rest.','休闲'),C('solitude.s2','情绪','The sudden solitude after her friends moved away felt painful rather than peaceful.','朋友搬走后突然到来的孤独感让她痛苦，而非平静。','the solitude of + place/situation; feel solitude','名词也可强调与人分离带来的孤寂感。','separation feels painful.','情绪')],M('He sought solitude in the cabin but invited fifty guests to stay with him.','He sought solitude in the cabin and spent the weekend alone.','与许多客人同住不符合寻求独处。','meaning'),[Q(1,'Enjoying solitude means enjoying…','time alone without other people nearby','a crowded party','a legal agreement','The first sense is the state of being alone.','meaning'),Q(2,'Painful solitude after friends move away suggests…','loneliness caused by separation','a peaceful holiday chosen for rest','a solid metal block','The second sense carries emotional isolation.','context'),Q(1,'Which phrase is natural?','seek solitude in a cabin','seek solitude with a crowd','solitude to seek of cabin','Seek solitude is a natural collocation.','collocation'),Q(1,'Solitude comes from a Latin noun related to…','being alone','melting wax','a public song','The Latin family is based on solus, alone.','word-formation')]);
P('solo','Solo comes from Italian solo, from Latin solus “alone”; it can be a musical piece/performance, an adjective for one person, an adverb meaning alone, or a verb meaning perform alone.',[C('solo.s1','音乐','The violinist played a short solo before the orchestra returned.','管弦乐队重新演奏前，小提琴手演奏了一段短独奏。','play/perform a solo; violin solo','名词，指由一人演奏或演唱的乐段、表演。','one performer has a featured passage.','音乐'),C('solo.s2','活动','She made her first solo flight after months of supervised lessons.','经过数月监督训练后，她完成了首次单人飞行。','a solo trip/flight; a solo performance','形容词，指由一人单独完成或参加。','flight has no other pilot aboard.','活动'),C('solo.s3','活动','The climber travelled solo through the valley, carrying all her equipment.','登山者独自带着全部装备穿过山谷。','travel/work solo; go solo','副词，表示独自、没有同伴。','travels without a companion.','活动'),C('solo.s4','音乐','The singer will solo during the final section of the concert.','这位歌手将在音乐会最后一段独唱。','solo on an instrument; solo in a concert','动词，指独自进行音乐表演。','singer performs alone.','音乐')],M('The violinist played a solo with the entire orchestra playing the same melody throughout.','The violinist played a solo while the orchestra paused to feature the individual part.','solo是突出个人演奏的乐段，不是全体持续齐奏。','distinction'),[Q(1,'A violin solo is…','a passage featured for one performer','a full orchestra playing together throughout','a shoe bottom','Solo sense 1 is an individual musical performance.','meaning'),Q(2,'A solo flight is made…','by one pilot without another pilot aboard','by a whole choir','only after the plane is sold','Solo as adjective means by one person.','context'),Q(3,'If a climber travels solo, she travels…','alone','with a tour group','inside a soundproof booth','Solo as adverb means alone.','meaning'),Q(4,'The singer will solo means the singer will…','perform alone','repair the stage','stop the music permanently','Solo as a verb means perform individually.','meaning')]);
P('solo piece','Solo piece combines solo and piece; solo came to English from Italian via Latin solus, “alone,” and the phrase names music performed by one musician without accompaniment.',C('solo piece.s1','音乐','The flutist chose a solo piece that could be performed without piano accompaniment.','长笛手选了一首无需钢琴伴奏即可演奏的独奏曲。','a solo piece for flute; perform a solo piece','名词短语，指由单个表演者独自演奏或演唱的作品。','one flutist performs without accompaniment.','音乐'),M('She selected a solo piece for flute, then required a full choir and orchestra to perform every note.','She selected a solo piece for flute that one performer could play alone.','独奏作品由单个表演者演出，不以合唱团和乐队齐奏为特征。','meaning'),[Q(1,'A flute solo piece is…','a work performed by one flutist without accompaniment','a composition that requires a full choir','a flat fish served with lemon','That is the source sense of solo piece.','meaning'),Q(1,'Why could the chosen piece be performed by the flutist alone?','It needed no piano accompaniment.','It required a second orchestra.','It was a solemn legal document.','The context explicitly says there was no accompaniment.','context'),Q(1,'Which phrase is natural?','a solo piece for flute','a solo piece at flute without','a piece soloing for the flutistly','For names the instrument in this phrase.','grammar'),Q(1,'Solo ultimately comes from Latin…','solus, “alone”','solidus, “firm”','sonus, “sound”','The phrase uses solo in the sense of one performer.','word-formation')]);
P('soloist','Soloist is formed from solo + -ist; it names a musician who performs a solo, with or without accompaniment.',C('soloist.s1','音乐','The soloist began the concerto while the orchestra waited for her cue.','独奏者开始演奏协奏曲时，管弦乐队等候她的提示。','a violin/piano soloist; the soloist performs','名词，指演奏或演唱独奏部分的音乐家。','one featured musician starts.','音乐'),M('The soloist performed the concerto, but every note was played by the orchestra and the featured musician stayed silent.','The soloist performed the featured part while the orchestra accompanied her.','soloist应实际演奏或演唱独奏部分。','meaning'),[Q(1,'A soloist is…','a musician who performs a solo','a person who repairs musical instruments','a choir consisting of many singers','The entry defines a soloist as the performer of a solo.','meaning'),Q(1,'Who began the concerto in the example?','The featured soloist','The audience conductor','A technician tuning the lights','The soloist starts the featured musical part.','context'),Q(1,'Which phrase is standard?','the piano soloist performed','the piano solo performed soloistly','the soloist of piano to performed','Piano modifies soloist as a compound noun.','grammar'),Q(1,'The suffix -ist here identifies…','a person who performs the music','a quality of being alone','a past event','Soloist names the musician.','word-formation')]);
P('solubility','Solubility is formed from soluble + -ity; it describes how readily a substance dissolves or the maximum amount that can dissolve under stated conditions.',C('solubility.s1','化学','The experiment compared the solubility of salt and sugar in cold water.','实验比较了盐和糖在冷水中的溶解度。','solubility in water; measure/compare solubility','名词，指物质溶解的容易程度或能够溶解的量。','compares how much dissolves in same solvent.','化学'),M('The high solubility of the salt meant that none of it could dissolve in water.','The salt’s solubility meant that it could dissolve readily in water.','溶解性高表示更容易或更多地溶解。','meaning'),[Q(1,'Solubility describes…','how readily or how much a substance dissolves','how loud a liquid sounds','how quickly a solid freezes','That is the chemistry sense.','meaning'),Q(1,'Why compare salt and sugar in cold water?','To compare their solubility under the same conditions','To test which one is a soloist','To measure water’s solemnity','The experiment measures dissolving behavior.','context'),Q(1,'Which phrase is natural?','the solubility of sugar in water','the soluble of sugarly water','sugar solubility to in water','Of links the quality to the substance.','grammar'),Q(1,'Solubility is formed from soluble plus…','-ity','-ist','-less','The suffix turns the adjective into a noun for a property.','word-formation')]);
P('soluble','Soluble comes from Latin solubilis, from solvere “loosen, release”; it means able to dissolve in liquid and, figuratively, capable of being solved.',[C('soluble.s1','化学','This powder is soluble in warm water, so it disappears after a few stirs.','这种粉末可溶于温水，搅拌几下就会消失。','soluble in water/alcohol; water-soluble','形容词，表示可在液体中溶解。','powder dissolves.','化学'),C('soluble.s2','问题','The puzzle seemed difficult, but it was soluble once the clues were arranged in order.','这个谜题看似很难，但线索按顺序排列后就能解开。','a soluble problem; prove a question soluble','形容词也可表示问题能够解决或解释。','ordered clues enable solution.','问题')],M('The powder was soluble in water, yet it remained as an undissolved lump after stirring.','The powder was soluble in water and dissolved after stirring.','仍未溶解的粉团说明此处并未溶解。','meaning'),[Q(1,'A powder soluble in warm water…','can dissolve in that liquid','cannot be mixed with any liquid','must become a gas','Soluble sense 1 means able to dissolve.','meaning'),Q(2,'A soluble puzzle is one that…','can be solved','has no possible answer','is made of sugar','Sense 2 applies figuratively to problems.','context'),Q(1,'Which phrase is correct?','soluble in water','soluble with waterly','soluble on the water','The usual preposition is in.','collocation'),Q(1,'The Latin verb behind soluble meant…','loosen or release','sound loudly','make a promise','Soluble is related to solvere.','word-formation')]);
P('solute','Solute comes from Latin solutus, the past participle of solvere “loosen, dissolve”; in a solution it is the substance dissolved in a solvent.',C('solute.s1','化学','When sugar dissolves in tea, sugar is the solute and the water-based liquid is the solvent.','糖溶解在茶中时，糖是溶质，水性液体是溶剂。','solute dissolves in a solvent; identify the solute','名词，指在溶液中被溶解的物质。','sugar is the dissolved substance.','化学'),M('In sugar water, the water is the solute because it is the substance dissolved by the sugar.','In sugar water, sugar is the solute because it dissolves in the water.','溶质是被溶解的物质；此例中是糖。','distinction'),[Q(1,'In sugar water, the solute is…','the sugar that dissolves','the water that dissolves it','the container holding the mixture','The solute is the dissolved substance.','meaning'),Q(1,'How are solute and solvent related?','The solute dissolves in the solvent.','The solvent must always be a solid.','The solute is the empty container.','The example contrasts sugar with the water-based solvent.','context'),Q(1,'Which sentence uses solute correctly?','Salt is the solute in salt water.','The glass is the solute in salt water.','The solute dissolves the empty glass.','Salt is the substance dissolved in the water.','grammar'),Q(1,'Solute is historically linked to Latin solvere, meaning…','loosen or dissolve','stand alone','sing a poem','The word is from the Latin family of dissolving.','word-formation')]);
P('solution','Solution comes from Latin solutio, from solvere “loosen”; it means a way to deal with a problem, a correct answer, or a homogeneous liquid mixture.',[C('solution.s1','问题','Moving the meeting online was a practical solution to the transport strike.','把会议改到网上举行，是应对交通罢工的实际解决办法。','a solution to a problem; find/propose a solution','名词，指解决困难或问题的方法。','online meeting addresses transport disruption.','问题'),C('solution.s2','学习','Her solution to the equation matched the answer in the textbook.','她给方程求出的解与课本答案一致。','the solution to an equation/puzzle','名词，也指题目、谜题或方程的正确答案。','calculated answer is correct.','学习'),C('solution.s3','化学','The nurse prepared a saline solution for cleaning the wound.','护士配制了盐水溶液来清洗伤口。','a solution of salt in water; saline solution','名词，指溶质均匀溶在溶剂中形成的液体。','salt dissolves in liquid.','化学')],M('The nurse prepared a saline solution by leaving all the salt undissolved in a dry bowl.','The nurse prepared a saline solution by dissolving salt evenly in water.','盐水溶液要求盐溶在水中，而不是干燥未溶的盐。','distinction'),[Q(1,'An online meeting is a solution to…','a transport problem','an equation’s answer','a chemical mixture','Sense 1 is a way to deal with a difficulty.','meaning'),Q(2,'The solution to an equation is…','the correct answer','the liquid in which salt dissolves','a meeting scheduled online','Sense 2 refers to a correct mathematical result.','context'),Q(3,'A saline solution contains…','salt dissolved in liquid','dry salt alone','a solo violin passage','Sense 3 is the chemistry meaning.','meaning'),Q(1,'Which phrase is natural?','a solution to the problem','a solution of solve the problem','solution for to equationly','To commonly introduces the problem being addressed.','collocation')]);
P('solve','Solve is from Latin solvere “loosen, untie”; it means find a way to deal with a problem or find the correct answer to a puzzle, calculation, or crime.',[C('solve.s1','问题','The city formed a joint team to solve the shortage of safe drinking water.','市政府成立联合小组，解决安全饮用水短缺问题。','solve a problem/shortage; solve the issue','及物动词，指找到办法处理困难或问题。','team seeks a remedy for shortage.','问题'),C('solve.s2','推理','Investigators solved the theft by matching a print on the window to a suspect.','调查人员把窗户上的指纹与嫌疑人比对，侦破了盗窃案。','solve a puzzle/crime/equation','及物动词，也指求出题目答案或查明案件。','evidence identifies culprit.','推理')],M('The team solved the water shortage by hiding the only safe water supply from residents.','The team solved the water shortage by arranging a reliable supply of clean water.','隐藏水源会加剧问题，不是解决短缺。','meaning'),[Q(1,'To solve a shortage is to…','find a way to deal with it','make the shortage worse','describe it without action','Solve sense 1 means deal with a problem.','meaning'),Q(2,'Investigators solve a crime when they…','find out who committed it and how','write a poem about it','dissolve evidence in water','Sense 2 includes discovering the answer to a crime.','context'),Q(1,'Which phrase is correct?','solve the puzzle','solve to the puzzle','solve at the puzzle','Solve is a transitive verb taking a direct object.','grammar'),Q(1,'Solve is related to a Latin verb meaning…','loosen or untie','make solemn','sit alone','The figurative development is from untying a knot to resolving.','word-formation')]);
P('solvent','Solvent comes from Latin solvens, “loosening,” from solvere; it can be a liquid that dissolves another substance or an adjective meaning financially able to pay debts.',[C('solvent.s1','化学','The lab used ethanol as a solvent to dissolve the plant compounds.','实验室用乙醇作溶剂来溶解植物化合物。','a solvent for a substance; organic solvent','名词，指能溶解其他物质的液体。','ethanol dissolves compounds.','化学'),C('solvent.s2','金融','After restructuring its debt, the company remained solvent and paid suppliers on time.','重组债务后，公司仍有偿付能力，并按时向供应商付款。','remain/become solvent; a solvent business','形容词，指有足够资金履行债务。','company pays amounts owed.','金融')],M('The company was solvent, but it had no money to pay any supplier or debt.','The company was solvent and had enough funds to pay its debts.','有偿付能力意味着能偿还债务。','meaning'),[Q(1,'In the lab, ethanol is a solvent because it…','dissolves other compounds','is the substance being dissolved','cannot mix with any material','Solvent sense 1 names the dissolving liquid.','meaning'),Q(2,'A solvent company can…','pay the debts it owes','dissolve its creditors in ethanol','never conduct business','Sense 2 is financial solvency.','context'),Q(1,'Which phrase is natural?','a solvent for the compound','a solvent of the compoundly','solvent into the compound as','For introduces what the liquid dissolves.','collocation'),Q(1,'Solvent is historically related to Latin solvere, “to…”','loosen','sing','stand alone','The chemistry sense developed from the idea of loosening or dissolving.','word-formation')]);
P('somber','Somber entered English through French sombre; it means dark in color or serious and melancholy in mood.',[C('somber.s1','氛围','The film ended with a somber scene in which the family gathered at the empty house.','影片以一幕阴郁的场景结尾：一家人聚在空荡荡的房子里。','a somber mood/tone; somber news','形容词，指颜色暗淡，或气氛、情绪严肃忧郁。','empty house and loss create grave mood.','氛围'),C('somber.s1','颜色','He wore a somber gray suit to the memorial service.','他穿着一套暗灰色西装参加追思会。','somber colors/clothes','形容词也指颜色深暗、朴素。','dark gray clothing.','颜色')],M('The film’s somber ending was cheerful and brightly comic, with no sadness or seriousness.','The film’s somber ending was grave and melancholy.','严肃忧郁的结尾与明快喜剧式结尾相反。','meaning'),[Q(1,'A somber mood is…','serious and melancholy','playful and carefree','a liquid solution','Somber describes a grave mood.','meaning'),Q(1,'Why was the gray suit called somber?','It was dark and subdued in color.','It was bright pink and decorated with stars.','It was a musical solo.','Somber can describe dark colors.','context'),Q(1,'Which phrase is natural?','somber news','somberly news','a somberness news','Somber is an adjective before news.','grammar'),Q(1,'Somber entered English through…','French sombre','Italian solo','Latin solutus','The English word came through French.','word-formation')]);
P('sombre','Sombre is the British spelling variant of somber, from French sombre; it describes a dark appearance or a serious, sad atmosphere.',C('sombre.s1','氛围','The sombre lighting and quiet music suited the play’s tragic final scene.','昏暗的灯光和安静的音乐很适合这出戏悲剧性的最后一幕。','a sombre mood/atmosphere; sombre clothing','形容词，指阴暗、忧郁或严肃沉重的氛围。','dim lighting and tragic scene.','氛围'),M('The sombre lighting made the tragic scene look bright, festive, and carefree.','The sombre lighting made the tragic scene look dark and serious.','sombre表示阴暗或忧郁，不是明亮欢庆。','meaning'),[Q(1,'A sombre atmosphere is…','serious, sad, or dark','bright and celebratory','a soluble chemical','That is the word’s core sense.','meaning'),Q(1,'What suited the tragic final scene?','Dim lighting and quiet music','Bright party lights and loud jokes','A financial balance sheet','Those details create a sombre mood.','context'),Q(1,'Which spelling is a British variant?','sombre','somberly','sombar','Sombre is the common British spelling.','spelling'),Q(1,'Sombre came into English from French…','sombre','solitaire','solution','The English adjective was borrowed from French.','word-formation')]);
P('some','Some comes from Old English sum, “a certain one or amount”; as a determiner or adverb it marks an unspecified amount, an unnamed person or thing, part of a group, or approximation.',[C('some.s1','数量','Could I have some rice with the vegetables?','我能配些米饭和蔬菜一起吃吗？','some water/rice/time; some of + plural noun','限定词，表示数量不确切的一些，常用于肯定句和请求。','unspecified amount of rice.','数量'),C('some.s2','指称','Some person from the building office left a message for you.','大楼办公室有个人给你留了言。','some person/thing; some day','限定词，表示某个不具体说明或不知道的人、事物。','person is unnamed.','指称'),C('some.s3','部分','Some of the seedlings survived the frost, but the rest died.','有些幼苗熬过了霜冻，其余的都死了。','some of the group; some people','代词，表示群体中的一部分。','only part of seedlings survived.','部分'),C('some.s4','约数','The repair will take some three hours if no parts need replacing.','如果无需更换零件，维修大约要花三个小时。','some + number; some ten miles','数词前作副词，表示大约、差不多。','approximate duration.','约数')],M('Some of the seedlings survived, meaning that every single seedling survived the frost.','Some of the seedlings survived; only part of the group lived.','some表示部分时不等于全部。','meaning'),[Q(1,'“Some rice” refers to…','an unspecified amount of rice','one exactly named grain','the whole field of rice','Sense 1 is an indefinite amount.','meaning'),Q(2,'“Some person left a message” means…','an unnamed or unidentified person did so','a particular named person is identified','several people jointly wrote it','Sense 2 leaves the person unspecified.','context'),Q(3,'“Some of the seedlings survived” says…','a part of them survived','all of them survived','none of them existed','Sense 3 marks a portion of a group.','meaning'),Q(4,'“Some three hours” means…','approximately three hours','exactly three seconds','more than three days','Before a number, some can mean approximately.','meaning')]);
P('somebody','Somebody combines some + body and means an unnamed person; it can also mean a person of importance in a context.',[C('somebody.s1','指称','Somebody left a blue umbrella beside the library desk.','有人把一把蓝色雨伞落在了图书馆柜台旁。','somebody left/called; somebody else','代词，指身份不明或未说明的某个人。','identity is unknown.','指称'),C('somebody.s2','身份','After years of study, the young engineer hoped to become somebody in her field.','多年学习后，这位年轻工程师希望在自己的领域有所成就、成为重要人物。','become somebody; feel like somebody','代词，也可表示有地位或重要性的人。','wants recognition in profession.','身份')],M('Somebody left an umbrella, so the building manager knows exactly which named visitor owns it.','Somebody left an umbrella, but the owner’s identity is not known.','somebody用于指称身份不明的人。','meaning'),[Q(1,'Somebody left an umbrella means…','an unidentified person left it','the owner is named and known','nobody came to the library','The basic sense is an unnamed person.','meaning'),Q(2,'To become somebody in one’s field is to…','become an important or recognized person','become literally a body','leave the field permanently','This idiom means gain importance or recognition.','context'),Q(1,'Which sentence is correct?','Somebody has called you.','Somebody have called you.','A somebody has called you.','Somebody is grammatically singular here.','grammar'),Q(1,'Somebody is formed by combining some and…','body','day','where','The compound means some person.','word-formation')]);
P('someday','Someday combines some + day; it means at an unspecified future time, often in a hope or prediction.',C('someday.s1','时间','I hope to visit the island someday, when work gives me a longer break.','我希望将来有一天能去那座岛，等工作允许我休更长的假时。','someday in the future; hope to + verb someday','副词，指未来某个尚未确定的日子。','future visit is hoped for but undated.','时间'),M('She hopes to visit the island someday yesterday after returning home.','She hopes to visit the island someday in the future.','someday表示未来的不确定时间，不能与yesterday连用。','usage'),[Q(1,'A plan to visit someday is planned for…','an unspecified time in the future','a definite time yesterday','a regular daily schedule','Someday expresses an indefinite future time.','meaning'),Q(1,'Why has the traveler not set a date?','She is waiting for a future break from work.','She already visited yesterday.','The island is inside a library.','The context leaves the future time open.','context'),Q(1,'Which sentence uses someday correctly?','Maybe we will meet again someday.','Maybe we met again someday last week.','Someday every day we meet at noon.','Someday points to an unspecified future occasion.','grammar'),Q(1,'Someday is a compound of some and…','day','body','where','The word joins some with day.','word-formation')]);
P('somehow','Somehow combines some + how; it means by a method that is unknown or not specified, and can also express that something happened for an inexplicable reason.',[C('somehow.s1','方法','We somehow managed to carry the piano upstairs without damaging the wall.','我们不知用什么办法，竟把钢琴搬上楼且没有弄坏墙。','somehow manage to; find a way somehow','副词，表示以某种方式，具体方法不清楚。','method is not explained.','方法'),C('somehow.s2','原因','Somehow, the old photograph had returned to the exact drawer from which it vanished.','不知怎么回事，那张旧照片又回到了它原先消失的那个抽屉里。','somehow + clause; somehow happened','副词，表示由于说不清的原因、莫名其妙地。','return is unexplained.','原因')],M('We somehow managed to carry the piano upstairs by explaining the exact lifting method in detail.','We somehow managed to carry the piano upstairs, although the method was unclear.','若方法已经详细说明，就不是“不知用什么办法”。','meaning'),[Q(1,'They somehow carried the piano upstairs means…','they did it by a method that is not explained','they gave a complete technical account','they left it downstairs','Sense 1 leaves the method unclear.','meaning'),Q(2,'Somehow the photo returned means…','its return happened for an unexplained reason','someone proved exactly how it happened','the photo became a liquid','Sense 2 conveys an inexplicable event.','context'),Q(1,'Which sentence is natural?','Somehow, the key was back in the drawer.','Somehow the key back was drawerly.','The key somehow is backed in drawer.','Somehow can modify the clause to mark an unexplained event.','grammar'),Q(1,'Somehow is formed from some and…','how','body','time','The compound combines some with how.','word-formation')]);
P('someone','Someone combines some + one and means an unidentified person; in another use it means a person who is important or admired.',[C('someone.s1','指称','Someone from the maintenance team will call you after the inspection.','检查结束后，维修组会有人给你打电话。','someone will; someone else; someone from + group','代词，指身份未说明的某个人。','caller not identified.','指称'),C('someone.s2','身份','The scholarship helped her become someone whose research was known internationally.','这项奖学金帮助她成为一位研究成果享誉国际的重要人物。','become someone; someone important','代词，也可表示有名望或影响力的人。','research gains recognition.','身份')],M('Someone will call you, and the sentence tells us the caller’s exact name and identity.','Someone will call you, but the caller has not been identified.','someone的基本用法不指出具体身份。','meaning'),[Q(1,'Someone from maintenance means…','an unidentified member of that team','the whole team will call together','a named person already identified','The pronoun leaves the person unnamed.','meaning'),Q(2,'To become someone in research is to…','gain importance or recognition','become an anonymous caller','stop doing research','Sense 2 is an idiom for becoming notable.','context'),Q(1,'Which sentence is grammatical?','Someone has left a note.','Someone have left a note.','A someone has left note.','Someone takes singular agreement here.','grammar'),Q(1,'Someone combines some with…','one','day','how','The compound means some person.','word-formation')]);
P('someplace','Someplace is the compound of some + place, used informally to mean at or to an unspecified place.',C('someplace.s1','地点','Let’s find someplace quiet to talk before the next train arrives.','下一班火车到站前，我们找个安静的地方谈谈吧。','go/find someplace; someplace to + verb','副词，指在或到某个未具体说明的地方。','location is not named.','地点'),M('They went someplace, namely to the clearly identified room 204 in the east wing.','They went someplace nearby, but did not say which place.','明确指出具体房间就不是未说明地点。','meaning'),[Q(1,'Find someplace quiet means find…','an unspecified quiet place','the one named room 204','a person who is important','Someplace leaves the location unnamed.','meaning'),Q(1,'Why does the sentence use someplace?','The speakers have not named the location.','They have given an exact room number.','They are describing a future day.','The place is deliberately unspecified.','context'),Q(1,'Which phrase is natural?','go someplace warm','go somewherely warm','go warm someplace to','Someplace can follow a verb of movement.','grammar'),Q(1,'Someplace is formed from some plus…','place','time','how','The compound means an unspecified place.','word-formation')]);
P('somerset','Somerset is an older variant spelling of somersault, a word of uncertain ultimate origin; it names a complete roll of the body over the head.',C('somerset.s1','体操','The gymnast completed a somerset on the mat and landed on both feet.','体操运动员在垫子上翻了个筋斗，双脚稳稳落地。','do/turn a somerset; somerset over','名词，旧式拼法，指身体从头到脚翻转一周的动作。','body rolls head over heels.','体操'),M('The gymnast did a somerset while keeping both feet on the floor and never turning over.','The gymnast did a somerset by rolling head over heels on the mat.','筋斗包含身体翻转，而不是双脚固定在地上。','meaning'),[Q(1,'A somerset is…','a complete roll of the body head over heels','a short musical solo','a liquid solution','It is an old spelling of somersault.','meaning'),Q(1,'How did the gymnast complete the move?','She turned her body over on the mat.','She stayed upright without moving.','She dissolved the mat in water.','A somerset is a body roll.','context'),Q(1,'Which statement about spelling is accurate?','Somerset is an older spelling variant of somersault.','Somerset is the only modern spelling of soldier.','Somerset means the sole of a boot.','The entry notes the variant relationship.','spelling'),Q(1,'The deeper origin of somerset is…','uncertain','certainly Latin solus','certainly the word for a violin','The form is identified as a variant; ultimate history is uncertain.','word-formation')]);
P('something','Something combines some + thing; it means an unnamed thing, approximately a stated amount, or partly matching a description.',[C('something.s1','指称','There is something in the parcel that rattles when I lift it.','包裹里有个东西，我一提起来它就发出响声。','something in/on; something to + verb','代词，指没有具体说出或不知道是什么的事物。','object is unidentified.','指称'),C('something.s2','数量','The repair cost something like two hundred dollars, including the replacement part.','这次维修连同替换零件大约花了两百美元。','something like + number/amount','代词作数量表达，表示大约某个数字或数量。','approximate cost.','数量'),C('something.s3','评价','That little café is something of a local institution after serving the town for sixty years.','那家小咖啡馆服务小镇六十年后，算得上当地的一处老牌地标。','something of a + noun; be something','口语中表示某种程度上算得上某类人或事物。','partly qualifies as an institution.','评价')],M('Something in the parcel was rattling, so the speaker knew precisely that it was a glass vase.','Something in the parcel was rattling, but its identity was not known.','something用来指未具体说明的事物，不能同时断言已确知身份。','meaning'),[Q(1,'Something in the parcel refers to…','an unnamed or unidentified object','a fully identified object with no uncertainty','a person with a famous career','The basic pronoun sense is an unspecified thing.','meaning'),Q(2,'Something like two hundred dollars means…','approximately two hundred dollars','exactly two dollars','less than one cent','Something like can introduce an approximate amount.','context'),Q(3,'Something of a local institution means the café…','partly deserves that description','is certainly a government office','is an unidentified parcel','This expression means “to some extent a.”','meaning'),Q(1,'Which phrase is natural?','something of a surprise','something a surprise ofly','some thing of surprise isly','Something of a is a common construction.','grammar')]);
P('sometime','Sometime comes from some + time; as an adverb it means at an unspecified time, usually in the future, and as an adjective it means former or occasional.',[C('sometime.s1','时间','Let’s have lunch sometime next week when your schedule is clearer.','下周你日程更明确时，我们找个时间一起吃午饭吧。','sometime next week; call sometime','副词，指某个未确定的时间，常用于将来安排。','future date not fixed.','时间'),C('sometime.s2','经历','A sometime editor of the magazine returned for its anniversary celebration.','这本杂志的一位前编辑回到庆祝活动现场。','a sometime teacher/editor; sometime colleague','形容词，指从前担任某职务或偶尔担任某种角色。','editor held the position in the past.','经历')],M('Let’s meet sometime next week, at the fixed and already agreed hour of exactly nine on Tuesday.','Let’s meet sometime next week; we have not chosen an exact day or hour.','sometime表示时间尚未确定，不应说已有确切时刻。','meaning'),[Q(1,'Meet sometime next week means meet…','at an unspecified time next week','every day next week','at a precise time already stated','Sometime leaves the date or time open.','meaning'),Q(2,'A sometime editor is…','a former editor or one who edited occasionally','the magazine’s current full-time editor necessarily','a person who edits only this sentence','The adjective refers to a former or occasional role.','context'),Q(1,'Which spelling expresses an unspecified time?','sometime next week','some time next week only when counting duration','some-times next week','Sometime as one word is the adverb meaning at an unspecified time.','spelling'),Q(1,'Sometime is formed by joining some and…','time','thing','place','It is a compound of some and time.','word-formation')]);
P('sometimes','Sometimes is formed from some + times; it means on certain occasions, but not regularly or every time.',[C('sometimes.s1','频率','The ferry sometimes runs late when thick fog covers the harbor.','浓雾笼罩港口时，渡船有时会晚点。','sometimes do something; sometimes … and sometimes …','副词，指有些时候发生，但并非经常或每次都发生。','delay occurs on certain foggy occasions.','频率'),C('sometimes.s2','对比','He is sometimes cheerful and sometimes quiet, depending on how the meeting went.','他有时开朗，有时安静，取决于会议进行得如何。','sometimes A, sometimes B; not always','副词也用于与always、never等对比，表示情况时有时无。','mood varies rather than being constant.','对比')],M('The ferry sometimes runs late every single day without exception.','The ferry sometimes runs late, but it is on time on many other days.','sometimes表示并非每次发生，不能与every single day without exception等同。','meaning'),[Q(1,'If a ferry sometimes runs late, it is late…','on certain occasions, not regularly','every time without exception','never at all','Sometimes marks occasional frequency.','meaning'),Q(2,'Sometimes cheerful and sometimes quiet means his mood…','varies with the situation','is always cheerful','never changes','The second sense contrasts different occasions.','context'),Q(1,'Which sentence uses sometimes correctly?','We sometimes eat outside when the weather is mild.','We sometimes eat outside every single meal.','We sometimes never eat outside at all.','Sometimes means on some but not all occasions.','grammar'),Q(1,'Sometimes is based on some plus the plural of…','time','place','body','The adverb developed from some times.','word-formation')]);
P('somewhat','Somewhat is formed from some + what; as an adverb it means to a limited degree, or softens a statement by making it less categorical.',[C('somewhat.s1','程度','The replacement part was somewhat cheaper, though it still exceeded the repair budget.','替换零件便宜了一些，不过仍然超出维修预算。','somewhat + adjective/adverb; somewhat less/more','副词，表示在一定程度上、稍微。','price is lower to a degree.','程度'),C('somewhat.s2','表达','The report was somewhat incomplete, a careful way of saying several sections were missing.','报告有些不完整——委婉地说，就是缺了好几个部分。','somewhat + evaluative adjective','副词也可缓和语气，表示某种程度上如此。','speaker moderates a criticism.','表达')],M('The part was somewhat cheaper, meaning its price was exactly zero and it cost nothing.','The part was somewhat cheaper, meaning it cost a little less but was not free.','somewhat表示程度有限，不是完全免费。','meaning'),[Q(1,'Somewhat cheaper means…','a little cheaper, but not necessarily very cheap','free of charge','more expensive by definition','Somewhat marks a limited degree.','meaning'),Q(2,'Calling the report somewhat incomplete softens the statement by…','making the criticism less categorical','claiming no sections are missing','announcing it is perfect','Somewhat can qualify and soften an evaluation.','context'),Q(1,'Which phrase is standard?','somewhat difficult to explain','somewhat difficulty to explain','difficult somewhatly to explain','Somewhat modifies the adjective difficult.','grammar'),Q(1,'Somewhat is a compound of some and…','what','where','time','Its form joins some with what.','word-formation')]);
P('somewhere','Somewhere combines some + where; it means at or to an unspecified place and can also mean approximately a point within a range.',[C('somewhere.s1','地点','I left the spare key somewhere near the back entrance.','我把备用钥匙落在后门附近的某个地方了。','somewhere near/in; go somewhere','副词，表示在或到一个未具体说明的地点。','location is approximate and unnamed.','地点'),C('somewhere.s2','范围','The village lies somewhere between the river and the old highway.','这个村庄位于河流和旧公路之间的某个位置。','somewhere around/between + range','副词也可表示在某个大致的数值、时间或范围位置。','location is placed within a range.','范围')],M('I left the key somewhere near the entrance, meaning I know its exact position down to the centimeter.','I left the key somewhere near the entrance, but I cannot specify its exact position.','somewhere表示地点未确指，不是精确坐标。','meaning'),[Q(1,'The spare key is somewhere near the entrance means…','its exact location is not specified','it is certainly inside the lock','the speaker knows its precise coordinates','Somewhere marks an unnamed location.','meaning'),Q(2,'Somewhere between two roads identifies…','an approximate point within a range','a point outside both roads','a person who is important','The second use places something within an estimated range.','context'),Q(1,'Which sentence is correct?','We should go somewhere quiet.','We should go somewherely quiet.','Somewhere we quiet should go.','Somewhere can follow a verb of movement.','grammar'),Q(1,'Somewhere combines some with…','where','time','body','The compound refers to an unspecified place.','word-formation')]);
P('somewhere else','Somewhere else combines somewhere + else and means in, at, or to a different place from the one being discussed.',C('somewhere else.s1','地点','The café was full, so we looked for somewhere else to study.','咖啡馆坐满了人，所以我们另找了一个地方学习。','go/look/find somewhere else; somewhere else to + verb','副词短语，表示在别处、到别处，地点不同于当前所指。','seek another location.','地点'),M('The café was full, so we studied somewhere else in the same crowded café at the same table.','The café was full, so we moved to a different place to study.','somewhere else表示另一个地方，而非同一地点。','meaning'),[Q(1,'Look for somewhere else means look for…','a different place','the same seat in the same place','an unspecified future day','Else marks a place different from the one mentioned.','meaning'),Q(1,'Why did the students search somewhere else?','The café was full.','They wanted to stay at the same crowded table.','They were looking for a solution in water.','The context gives the reason to move to another place.','context'),Q(1,'Which phrase is natural?','Is there somewhere else we can meet?','Is there elsewhere somewhere can meet?','Can somewhere else is meeting us?','Somewhere else can be followed by a relative clause.','grammar'),Q(1,'Else in somewhere else adds the idea of…','another or different','exactly the same','an approximate quantity','Else marks an alternative location.','meaning')]);
P('son','Son comes from Old English sunu, from a Germanic family; it means a male child in relation to parents and can also mean a male descendant or friendly form of address.',[C('son.s1','家庭','Their son starts secondary school in September.','他们的儿子九月开始上中学。','someone’s son; a son of + parent','名词，指某人的男性子女。','child’s relation to parents.','家庭'),C('son.s2','称呼','The old farmer greeted the young visitor with “Come in, son.”','老农向年轻来客打招呼说：“进来吧，小伙子。”','my son; come here, son','名词，也可书面指男性后代，或亲切地称呼男孩、年轻男子。','friendly address to young man.','称呼')],M('Their son starts school in September; she is their male child.','Their daughter starts school in September; she is their female child.','son特指男性子女；句中she和female child与之矛盾。','distinction'),[Q(1,'In a family, a son is…','a male child of a parent','a female child of a parent','a parent’s brother','The first sense is a male child in relation to parents.','meaning'),Q(2,'When the farmer says “Come in, son,” he may be…','addressing a young man warmly','stating the visitor is his biological child for certain','asking a woman to leave','Son can be a friendly form of address.','context'),Q(1,'Which phrase is natural?','their son and daughter','their son and daughters is','their son of daughter','Son pairs naturally with daughter as a family term.','grammar'),Q(1,'Son comes from Old English…','sunu','solus','sonus','The English noun descends from Old English sunu.','word-formation')]);
P('sonar','Sonar is an acronym formed from “sound navigation and ranging”; it uses sound echoes to locate underwater objects.',C('sonar.s1','航海','The research vessel used sonar to map a rocky ridge beneath the water.','科考船用声纳绘制水下岩脊的地形。','use sonar to locate/map; sonar equipment','名词，指发射声波并分析回声以探测水下物体的设备或系统。','sound echoes reveal underwater ridge.','航海'),M('The vessel used sonar to locate the ridge by measuring sunlight reflected from the seabed.','The vessel used sonar to locate the ridge by sending sound waves and reading their echoes.','声纳依靠声波回声，不靠测量阳光。','distinction'),[Q(1,'Sonar locates underwater objects by…','sending sound waves and reading echoes','measuring reflected sunlight only','sending written messages','That is the equipment’s source function.','meaning'),Q(1,'What did the vessel map with sonar?','A rocky underwater ridge','A city street above ground','A piece of sheet music','The context concerns a feature below the water.','context'),Q(1,'Sonar is an acronym for…','sound navigation and ranging','sole navigation and reading','sonic nature and rhythm','The letters come from sound navigation and ranging.','word-formation'),Q(1,'Which collocation is natural?','use sonar to map the seabed','use sonar at singing a poem','sonar of the shipwise','Sonar is commonly used to locate or map underwater features.','collocation')]);
P('sonata','Sonata comes from Italian sonata, from sonare “to sound”; it is an instrumental composition, typically in several movements, for a soloist or small ensemble.',C('sonata.s1','音乐','The pianist rehearsed the final movement of the sonata before the recital.','钢琴家在独奏会上演出前排练了奏鸣曲的最后一个乐章。','a piano/violin sonata; a sonata in + key','名词，指由独奏者或小型合奏演奏的器乐作品，通常分成几个乐章。','instrumental work has movements.','音乐'),M('The singer performed a sonata whose entire score consisted of spoken dialogue and no instruments.','The pianist performed a sonata written for instruments and organized into movements.','sonata是器乐作品，不是纯对白剧本。','meaning'),[Q(1,'A sonata is primarily…','an instrumental composition in movements','a songbird’s call','a legal promise','That is the source definition.','meaning'),Q(1,'What did the pianist rehearse?','The final movement of the instrumental work','A chemical solution','A military supply route','A sonata commonly has multiple movements.','context'),Q(1,'Which phrase is natural?','a sonata for violin and piano','a sonata of singing dialogue only','a sonata to the stage actorly','For can introduce the instruments written for the piece.','grammar'),Q(1,'Sonata came through Italian from a verb meaning…','to sound','to dissolve','to be alone','The Italian word is related to sonare.','word-formation')]);
P('song','Song comes from Old English sang, related to sing; it is a piece of music with words or the act/sound of singing, including birdsong.',[C('song.s1','音乐','The children learned a song about the seasons for the school concert.','孩子们为学校音乐会学了一首关于四季的歌。','sing/write a song; a song about + topic','名词，指有歌词并演唱的音乐作品。','children learn lyrics and tune.','音乐'),C('song.s2','自然','At dawn, the song of the blackbird carried across the garden.','黎明时，乌鸫的鸣唱传遍了花园。','birdsong; the song of a bird; burst into song','名词也可指歌唱行为或鸟类发出的悦耳鸣声。','bird produces musical call.','自然')],M('The children learned a song for the concert, but it had no music, words, or singing.','The children learned a song with words and a melody to sing at the concert.','歌通常是有歌词和曲调、可以演唱的作品。','meaning'),[Q(1,'A song about the seasons is…','a musical work that is sung','a bird’s nest','an instrumental legal form','The first sense is an item of vocal music.','meaning'),Q(2,'The song of a blackbird is…','its musical call','a written school timetable','a soloist’s contract','Song also describes birds’ musical sounds.','context'),Q(1,'Which phrase is natural?','write a song about winter','write a song winterly aboutly','song a winter write of','About introduces the topic of a song.','grammar'),Q(1,'Song is related to the Old English verb…','sing','solder','solve','The words song and sing share an old Germanic family.','word-formation')]);
P('songbird','Songbird combines song + bird and names a bird, especially a perching bird, known for its musical call.',C('songbird.s1','鸟类','A songbird perched on the fence and sang while the gardeners worked.','一只鸣禽落在篱笆上，在园丁干活时鸣唱。','a small songbird; songbird calls','名词，指会发出悦耳鸣声的鸟，尤指雀形目鸣禽。','bird sings from a perch.','鸟类'),M('The songbird perched on the fence but made no call and was described only as a silent water fish.','The songbird perched on the fence and gave a musical call.','songbird的特征是鸟鸣，不是鱼。','meaning'),[Q(1,'A songbird is a bird especially known for…','its musical call','its ability to dissolve in water','its role in a sonata','The word names a bird with a musical call.','meaning'),Q(1,'What did the songbird do in the garden?','Perched and sang while gardeners worked','Built a bridge under water','Played the piano alone','The example explicitly describes its call.','context'),Q(1,'Which phrase is natural?','a songbird perched on the fence','a songbirdly perched fence on','a bird songing fence of','Songbird is a compound noun.','grammar'),Q(1,'Songbird is formed from song and…','bird','word','time','The compound transparently names a singing bird.','word-formation')]);
P('songwriter','Songwriter combines song + write + -er; it names someone who composes songs by writing lyrics, music, or both.',C('songwriter.s1','职业','The songwriter drafted a new chorus after testing the melody with the band.','这位歌曲作者和乐队试唱旋律后，写出了新的副歌。','a songwriter writes/composes songs; singer-songwriter','名词，指创作歌词、旋律或两者的歌曲作者。','writer revises song material.','职业'),M('The songwriter was responsible for the song’s creation but never wrote lyrics, music, or any part of it.','The songwriter wrote the lyrics and melody for the new song.','songwriter的工作是创作歌曲内容。','meaning'),[Q(1,'A songwriter is someone who…','composes songs, writing words, music, or both','only repairs microphones','performs every song without writing any','That is the entry’s definition.','meaning'),Q(1,'Why did the songwriter draft a new chorus?','The melody had been tested with the band.','The chorus was a chemical solvent.','The band had no songs at all.','The context shows song composition and revision.','context'),Q(1,'Which phrase is correct?','a songwriter wrote the lyrics','a songwrite wrote the lyrics','a songwriterly wrote lyrics','Songwriter is the noun for the person.','grammar'),Q(1,'The suffix -er in songwriter refers to…','a person who writes songs','a quality of being musical','a collection of birds','The word names the person doing the writing.','word-formation')]);
P('sonic','Sonic comes from Latin sonus, “sound”; it means relating to or using sound waves and can refer to the speed of sound.',C('sonic.s1','声学','The instrument emits sonic pulses that reveal cracks inside the concrete wall.','这台仪器发出声波脉冲，用来探测混凝土墙内部的裂缝。','sonic waves/pulses; sonic device','形容词，指与声音或声波有关、利用声波的。','sound pulses inspect material.','声学'),M('The sonic sensor found the crack by detecting a smell rather than any sound wave.','The sonic sensor found the crack by detecting reflected sound waves.','sonic检测依赖声波，不是气味。','meaning'),[Q(1,'A sonic pulse is related to…','sound or a sound wave','a silent color','a legal office','Sonic means of or using sound.','meaning'),Q(1,'How did the instrument detect cracks?','It emitted sonic pulses into the wall.','It measured the wall’s smell.','It asked a songbird to inspect the concrete.','Sound pulses can reveal internal flaws.','context'),Q(1,'Which phrase is natural?','sonic waves travel through the material','sonically waves travel materially','waves sonic to material at','Sonic modifies the noun waves.','grammar'),Q(1,'Sonic is derived from Latin sonus, meaning…','sound','alone','firm','The Latin root gives the sound-related meaning.','word-formation')]);
P('sonnet','Sonnet came through French from Italian sonetto, “little song,” a diminutive of sonus; it is a fourteen-line poem with a traditional meter and rhyme pattern.',C('sonnet.s1','文学','The students compared the rhyme scheme of a Shakespearean sonnet with a modern free-verse poem.','学生们比较了一首莎士比亚十四行诗的押韵格式和一首现代自由诗。','write/read a sonnet; Shakespearean sonnet','名词，指通常由十四行组成、讲究格律和韵式的诗体。','fourteen lines and rhyme are examined.','文学'),M('She called the poem a sonnet, though it had only three lines and no planned meter or rhyme.','She called the fourteen-line poem a sonnet because it followed a traditional rhyme pattern.','十四行及传统格律、韵式是sonnet的重要特征。','meaning'),[Q(1,'A sonnet traditionally has…','fourteen lines','fourteen chapters','three lines only','The defining poetic form has fourteen lines.','meaning'),Q(1,'What did students compare?','The rhyme scheme of a sonnet and free verse','Two chemical mixtures','A singer and a bird','The context focuses on poetic form.','context'),Q(1,'Which phrase is natural?','write a sonnet about winter','write a sonnet winterly to','sonnet the winter write','About introduces the poem’s subject.','grammar'),Q(1,'Sonnet came through Italian sonetto, meaning…','little song','large soldier','flat fish','Sonetto is a diminutive related to song/sound.','word-formation')]);
P('soon','Soon comes from Old English sona, “immediately, presently”; it can mean in a short time, early, or in would sooner express preference.',[C('soon.s1','时间','The repair crew will arrive soon, so keep the entrance clear.','维修人员很快就会到，请保持入口畅通。','soon after; arrive soon; as soon as','副词，指从现在起不久、很快。','arrival is expected shortly.','时间'),C('soon.s2','早晚','We reached the station sooner than expected and waited for the first train.','我们比预想更早到达车站，于是等候首班列车。','sooner than expected; sooner rather than later','副词也可表示较早、早于预期。','arrival is earlier than forecast.','早晚'),C('soon.s3','偏好','I would soon walk home than wait another hour for the bus.','我宁愿步行回家，也不愿再等一小时公交。','would sooner do A than B','用于would sooner结构，表示宁愿选择一事而不做另一事。','prefers walking to waiting.','偏好')],M('The crew will arrive soon, meaning they are expected many years from now.','The crew will arrive soon, meaning they are expected in a short time.','soon指不久之后，不是多年以后。','meaning'),[Q(1,'The crew will arrive soon means…','they will arrive in a short time','they may arrive decades later','they have already left forever','Sense 1 means presently or shortly.','meaning'),Q(2,'If someone arrives sooner than expected, they arrive…','earlier than predicted','later than predicted','at exactly the same time as predicted','Sense 2 compares timing.','context'),Q(3,'“I would sooner walk than wait” means…','I prefer walking to waiting','I must wait before walking','I dislike both options equally','Would sooner expresses preference between actions.','meaning'),Q(1,'Which phrase is natural?','as soon as the bus arrives','as soon the busly arrives','soon as arrival the bus','As soon as introduces the immediate next event.','grammar')]);
P('sooner','Sooner is the comparative of soon; it means earlier or after a shorter wait, and in would sooner it expresses preference.',[C('sooner.s1','时间','If you leave sooner, you can avoid the traffic near the stadium.','如果你早点出发，就能避开体育场附近的交通。','sooner than; sooner or later; leave sooner','副词比较级，表示比另一时间更早或等待时间更短。','leaving earlier avoids traffic.','时间'),C('sooner.s2','偏好','They would sooner repair the old bridge than close the only road.','他们宁愿修好旧桥，也不愿封闭唯一的道路。','would sooner do A than B','用于would sooner结构，表示更愿意做前一件事。','repair is preferred to closure.','偏好')],M('The bus arrived sooner than the train, meaning it arrived later after a longer wait.','The bus arrived sooner than the train, meaning it came earlier.','sooner表示更早或等待更短。','meaning'),[Q(1,'Leave sooner to avoid traffic means leave…','earlier','later','after traffic has ended next month','The comparative concerns an earlier time.','meaning'),Q(2,'They would sooner repair than close the road means they…','prefer repairing the bridge','prefer closing the road','have already closed both routes','Would sooner marks preference.','context'),Q(1,'Which construction is correct?','sooner than the train','sooner that the train','sooner to the train','Than introduces the comparison.','grammar'),Q(1,'Sooner is the comparative form of…','soon','some','sound','It adds the comparative ending to soon.','word-formation')]);
P('sooner than','Sooner than appears in two established patterns: would sooner A than B expresses preference; otherwise it means earlier than a stated event or time.',[C('sooner than.s1','偏好','The residents would sooner repair the bridge than take a forty-mile detour.','居民宁愿修桥，也不愿绕行四十英里。','would sooner A than B','结构would sooner … than …表示宁愿做前者而不做后者。','repair is preferred to detour.','偏好'),C('sooner than.s2','时间','The package arrived sooner than the delivery estimate suggested.','包裹比预计送达时间更早到达。','sooner than expected/promised; arrive sooner than + event','比较时间时表示早于所提到的时间或事件。','arrival precedes estimate.','时间')],M('The package arrived sooner than estimated, meaning it arrived after the predicted delivery date.','The package arrived sooner than estimated, meaning it came before the predicted date.','sooner than表示更早，不是更晚。','meaning'),[Q(1,'“Would sooner repair than detour” means residents…','prefer repairing to taking the detour','prefer the detour and reject repairs','must do both actions at once','This is the preference construction.','meaning'),Q(2,'“Arrived sooner than estimated” means it came…','before the predicted time','after the predicted time','at an unknown place','The time-comparison use means earlier.','context'),Q(1,'Which pattern expresses preference?','would sooner stay than leave','sooner than expected arrival','sooner at the bridge','Would sooner A than B contrasts preferred actions.','grammar'),Q(1,'In the time comparison, sooner than means…','earlier than','more expensive than','at the same time as','It compares an earlier time with a reference.','meaning')]);
P('soot','Soot is an old Germanic word for the fine black carbon powder deposited by smoke from burning fuel.',C('soot.s1','环境','A layer of soot covered the chimney bricks after the old stove burned coal all winter.','旧炉子整个冬天烧煤后，烟囱砖上覆了一层煤烟。','soot from smoke; a layer/coating of soot','名词，不可数，指燃烧烟气沉积的黑色碳粉。','smoke deposits black particles.','环境'),M('The clean chimney was covered with white frost called soot from water vapour.','The chimney was covered with black soot deposited by smoke.','soot是烟熏沉积的黑色碳质粉末，不是白霜。','distinction'),[Q(1,'Soot is…','black carbon powder left by smoke','white frost from water','a piece of music','That is the source definition.','meaning'),Q(1,'What caused the coating in the example?','Burning coal in the stove','A soloist’s rehearsal','A dissolved sugar solution','Smoke from burned fuel deposits soot.','context'),Q(1,'Which phrase is natural?','a layer of soot on the bricks','a soot of layerly bricks','many sootses on brick','Soot is generally an uncountable material noun.','countability'),Q(1,'Soot is historically a word from…','an old Germanic language family','Italian music terminology','the Latin for alone','Its history is Germanic.','word-formation')]);
P('soothe','Soothe is an old English verb of uncertain deeper origin; it means calm someone or relieve pain, irritation, or distress.',[C('soothe.s1','情绪','Her quiet voice helped soothe the frightened child after the thunderstorm.','雷雨过后，她轻柔的声音安抚了受惊的孩子。','soothe someone; soothe a child’s fears','及物动词，指使人平静、安心。','voice calms child.','情绪'),C('soothe.s2','健康','A cool cloth soothed the irritation around the patient’s eyes.','凉布缓解了患者眼周的刺激感。','soothe pain/irritation; soothing cream','动词也指减轻疼痛、刺激或不适。','cool cloth eases discomfort.','健康')],M('The cool cloth soothed the irritation by making the burning and discomfort much worse.','The cool cloth soothed the irritation by easing the burning discomfort.','soothe表示缓解不适，不是加重症状。','meaning'),[Q(1,'A voice that soothes a child…','calms the child','makes the child more frightened','dissolves the child’s toys','Sense 1 is calming a person.','meaning'),Q(2,'A cloth soothed irritation by…','easing the discomfort','increasing the burning','making no contact with the skin','Sense 2 means relieve pain or irritation.','context'),Q(1,'Which phrase is natural?','soothe someone’s fears','soothe to someone’s fears','sootheful the fear of','Soothe can take a person or feeling as its object.','grammar'),Q(1,'The deeper origin of soothe is…','uncertain','certainly Latin solus','certainly Greek for music','No specific deeper etymology is asserted here.','word-formation')]);
P('sophism','Sophism comes from Greek sophisma, “clever device or argument”; it is a plausible-sounding but fallacious argument used to mislead.',C('sophism.s1','逻辑','The debater exposed the sophism by showing that its conclusion did not follow from its evidence.','辩手指出结论并不能由证据推出，从而揭穿了这套诡辩。','expose a sophism; a plausible sophism','名词，指看似合理、实则错误并意在误导的论证。','the inference is invalid.','逻辑'),M('Her sophism was a valid proof whose conclusion followed necessarily from verified premises.','Her sophism sounded persuasive but relied on a false inference.','有效且必然成立的证明不是诡辩。','distinction'),[Q(1,'A sophism is an argument that…','sounds plausible but is fallacious','is necessarily a valid proof','contains no reasoning at all','That is the word’s core sense.','meaning'),Q(1,'How did the debater expose the sophism?','She showed the conclusion did not follow from the evidence.','She proved every premise beyond doubt.','She played a sonata.','The defect lay in the invalid inference.','context'),Q(1,'Which phrase is natural?','expose a sophism','expose a sophismly','expose to sophism of','Sophism is the direct object of expose.','grammar'),Q(1,'Sophism is historically from Greek…','sophisma, “clever device or argument”','solus, “alone”','sonus, “sound”','The Greek term referred to a clever device or argument.','word-formation')]);
P('sophist','Sophist comes from Greek sophistēs, “wise man or expert”; it can mean someone using specious reasoning or, historically, a paid teacher of rhetoric in ancient Greece.',[C('sophist.s1','论辩','The sophist twisted the evidence into a convincing but misleading argument.','这名诡辩家把证据曲解成了有说服力却误导人的论点。','a sophist uses specious reasoning','名词，指使用似是而非论证的人；历史上也指古希腊收费教授修辞等学问的教师。','reasoning misleads despite persuasive sound.','论辩'),C('sophist.s1','古希腊','The lecture described how an ancient Greek sophist taught rhetoric to students for a fee.','讲座介绍了一位古希腊智者如何收费教授学生修辞术。','the Greek sophists; a teacher of rhetoric','此历史用法指古希腊收费教授修辞、哲学等学问的教师。','paid teaching of rhetoric.','古希腊')],M('The sophist carefully presented a valid proof without trying to make false reasoning look convincing.','The sophist used plausible-sounding reasoning to mislead the audience.','现代常用义强调似是而非的论证。','meaning'),[Q(1,'A modern sophist may…','use persuasive but specious reasoning','teach only arithmetic without speaking','sing a songbird’s call','The sense concerns misleading argument.','meaning'),Q(1,'An ancient Greek sophist was often…','a paid teacher of rhetoric','a soldier serving without pay','a black powder from smoke','Historically, sophists taught rhetoric for a fee.','context'),Q(1,'Which phrase is natural?','a sophist argued for the policy','a sophist argumented the policyly','sophist to the argument at','The noun refers to the person making the argument.','grammar'),Q(1,'Sophist comes from Greek sophistēs, meaning…','wise man or expert','flat fish','a liquid solvent','The historical Greek term referred to a wise or skilled person.','word-formation')]);
P('sophisticate','Sophisticate is from sophisticated, ultimately related to Greek sophistes; as a noun it is a worldly person, and as a verb it means make something more complex or adulterate it.',[C('sophisticate.s1','社交','The young sophisticate knew which gallery openings required reservations.','这位年轻的世故人士知道哪些画廊开幕活动需要预约。','a worldly sophisticate; a city sophisticate','名词，指见多识广、品味成熟老练的人。','person navigates cultural events confidently.','社交'),C('sophisticate.s2','工艺','The designer tried not to sophisticate the simple interface with unnecessary controls.','设计师尽量不在简洁的界面上添加多余控件，使它过于复杂。','sophisticate a design/system; overly sophisticated','动词，指使某物变得更复杂，或掺入其他物质。','extra controls add complexity.','工艺')],M('The designer sophisticated the interface by removing every extra control and making it simpler.','The designer avoided sophisticating the interface with extra controls.','动词sophisticate表示使复杂化或掺假，而不是简化。','word-choice'),[Q(1,'A worldly sophisticate is…','a person with polished experience and tastes','a person who has never seen a city','a musical instrument','The noun sense describes a worldly person.','meaning'),Q(2,'To sophisticate an interface may be to…','make it more complex','remove all complexity','repair its soundproofing','The verb sense includes increasing complexity.','context'),Q(1,'Which use is correct?','The editor tried not to sophisticate the simple design.','The editor sophisticate the design yesterday.','The editor was a sophisticatedly as a person.','After did/tried to, the verb remains in base form.','grammar'),Q(1,'Sophisticate is historically related to Greek…','sophistes','solus','solder','The word family goes back to Greek sophistes.','word-formation')]);
P('sophisticated','Sophisticated comes from sophisticate, ultimately Greek sophistes; it describes advanced complexity, worldly experience, or elegant style.',[C('sophisticated.s1','科技','The lab installed a sophisticated sensor that can detect tiny changes in air pressure.','实验室安装了一台精密传感器，能够检测气压的微小变化。','sophisticated equipment/system; highly sophisticated','形容词，指结构复杂、技术先进、功能精密。','instrument detects minute changes.','科技'),C('sophisticated.s2','阅历','Her sophisticated understanding of the market came from years of working with international clients.','她对市场的成熟理解来自多年服务国际客户的经历。','a sophisticated audience/understanding','形容词也指见多识广、判断成熟、有鉴赏力。','experience informs judgement.','阅历'),C('sophisticated.s3','风格','He wore a sophisticated black suit with a simple silver pin.','他穿着一套优雅精致的黑色西装，别着一枚简洁的银针。','a sophisticated style/design','形容词也可指风格高雅、时髦而精致。','restrained clothing looks elegant.','风格')],M('The sophisticated sensor was a crude device that could not register any pressure change.','The sophisticated sensor detected tiny pressure changes with advanced precision.','精密先进的设备不应被描述为粗糙且无法检测。','meaning'),[Q(1,'A sophisticated sensor is…','advanced and capable of precise detection','a simple device with no useful function','a person from ancient Greece','Sense 1 describes advanced complexity.','meaning'),Q(2,'A sophisticated market understanding suggests…','mature judgement developed through experience','complete unfamiliarity with the market','a machine measuring air pressure','Sense 2 describes worldly knowledge.','context'),Q(3,'A sophisticated style is…','elegant and refined','crude and unfinished','a chemical mixture','Sense 3 concerns polished appearance.','meaning'),Q(1,'Which phrase is natural?','a sophisticated system','a sophistication systemly','a system sophisticatedness','Sophisticated is an adjective modifying system.','grammar')]);
P('sophistication','Sophistication is formed from sophisticate + -ion and names technical complexity or worldly taste and polished manners.',[C('sophistication.s1','技术','The new navigation system has enough sophistication to reroute a driver around sudden road closures.','这套新导航系统足够先进，能在道路突然封闭时为司机重新规划路线。','technical sophistication; a degree of sophistication','名词，指技术、设计或方法的复杂精密程度。','system handles changing routes.','技术'),C('sophistication.s2','社交','Her quiet sophistication showed in the way she welcomed nervous first-time guests.','她从容得体地接待初次到访、略显紧张的客人，显出成熟的教养。','social sophistication; elegance and sophistication','名词也指成熟世故的品味、举止和判断力。','poised hospitality shows polished manners.','社交')],M('The navigation system’s sophistication was demonstrated by its inability to process even a simple road closure.','The navigation system’s sophistication let it reroute around a sudden road closure.','处理不了简单变化说明系统缺乏先进复杂的能力。','meaning'),[Q(1,'A navigation system’s sophistication concerns its…','advanced complexity and ability','colour alone','lack of any technical function','The first sense is high technical development.','meaning'),Q(2,'Social sophistication is shown by…','polished manners and mature taste','a system rerouting cars','loudness of a song','The second sense concerns worldly social qualities.','context'),Q(1,'Which phrase is natural?','the sophistication of the design','the sophisticated of designingly','the sophistication design at','Of links the quality to the design.','grammar'),Q(1,'Sophistication is formed from sophisticate with…','-ion','-less','-er','The suffix creates a noun naming a quality or state.','word-formation')]);
P('sophomore','Sophomore is an American term for a second-year student; its humorous historical formation combines Greek sophos “wise” and mōros “fool.”',C('sophomore.s1','教育','As a sophomore, Lina chose a research seminar after completing her first year at university.','完成大学一年级后，莉娜作为二年级学生选了一门研究研讨课。','a college/high-school sophomore; sophomore year','名词，指四年制中学或大学的二年级学生。','student has completed first year.','教育'),M('Lina was a sophomore in her first week of kindergarten, before beginning any secondary school or college year.','Lina became a sophomore in her second year at the university.','sophomore特指相关四年制中学或大学的第二年学生。','meaning'),[Q(1,'A university sophomore is a student in…','the second year','the first year only','the final doctoral year','That is the American educational sense.','meaning'),Q(1,'Why could Lina choose a research seminar?','She had completed her first university year.','She had not started school.','She was a songbird.','The context explicitly places her in year two.','context'),Q(1,'Which phrase is standard?','a sophomore at college','a sophomore of collegely','a sophomore to year first','At can introduce the institution where the student studies.','grammar'),Q(1,'The humorous Greek elements in sophomore mean…','wise and fool','sound and silence','alone and firm','Its formation joins sophos and moros.','word-formation')]);
P('soprano','Soprano comes from Italian soprano, from sopra “above”; it names the highest ordinary singing voice or a singer with that voice, and can modify music written for it.',[C('soprano.s1','音乐','The soprano held the final high note while the orchestra played softly beneath her.','管弦乐队轻声伴奏时，女高音歌手稳稳唱住了最后一个高音。','a lyric/dramatic soprano; sing soprano','名词，指通常最高的歌唱声部，也指演唱该声部的人。','singer sustains high register.','音乐'),C('soprano.s2','乐谱','The composer added a soprano line above the lower choral parts.','作曲家在较低的合唱声部上方加入了女高音声部。','soprano voice/part; soprano saxophone','形容词，表示为女高音声部编写或与其相关。','part is written for upper voice.','乐谱')],M('The soprano sang the lowest bass notes in the choir because soprano means the deepest voice.','The soprano sang the high line above the lower choral parts.','soprano指最高的常见歌唱声部，不是最低的男低音。','distinction'),[Q(1,'A soprano is associated with…','the highest ordinary singing voice','the lowest bass register','a soundproof room','Sense 1 is the high vocal range or its singer.','meaning'),Q(2,'A soprano line in a score is…','written for or related to the high voice','a line for the lowest bass only','a poem with fourteen lines','The adjective use labels the voice part.','context'),Q(1,'Which phrase is natural?','she sings soprano','she soprano singsly','she sings to the soprano voice at','Soprano can name the voice type after sing.','grammar'),Q(1,'Italian soprano is related to sopra, meaning…','above','below','alone','The name refers to the voice’s position above lower parts.','word-formation')]);
P('sorceress','Sorceress is formed from sorcerer + -ess; it means a woman believed to use supernatural magic, especially to harm others.',C('sorceress.s1','文学','In the tale, the sorceress cast a spell that turned the prince into stone.','故事中，女巫施下咒语，把王子变成了石头。','an evil/powerful sorceress; a sorceress casts a spell','名词，指被认为有魔法、尤其施法害人的女性。','woman uses magic in story.','文学'),M('The village called her a sorceress, although she was an ordinary doctor using no magic at all.','The village believed she was a sorceress because she used magic to harm people.','词义涉及被认为拥有并使用魔法的女性，不是普通医生。','meaning'),[Q(1,'A sorceress in the tale is…','a woman believed to have magical powers','a person who repairs shoes','a male soldier','That is the source sense.','meaning'),Q(1,'What did the sorceress do to the prince?','Cast a spell that turned him to stone','Sang him a sonnet','Solved his equation','The context depicts the woman using magic.','context'),Q(1,'Which phrase is natural?','a powerful sorceress cast a spell','a powerful sorceressly cast spell','sorceress to spell of cast','Sorceress is the subject of the verb cast.','grammar'),Q(1,'The suffix -ess traditionally marks…','a female person','a chemical substance','a place','It forms the feminine counterpart to sorcerer.','word-formation')]);
P('sorcery','Sorcery came through Old French sorcerie, from sorcier; it means the practice of using supernatural magic to control events or harm people.',C('sorcery.s1','文学','The villagers feared that the illness had been caused by sorcery.','村民们担心这场疾病是巫术造成的。','practice/belief in sorcery; use sorcery','名词，不可数，指运用魔法控制事件或伤害他人的做法。','illness attributed to magic.','文学'),M('The villagers called the doctor’s ordinary medicine sorcery, although it involved no magic or supernatural practice.','The villagers believed the illness was caused by sorcery, or supernatural magic.','此词指巫术，不是普通医学治疗。','distinction'),[Q(1,'Sorcery is…','the practice of using magical powers','a way to make a solid object','a kind of singing voice','The entry defines sorcery as the practice of magic.','meaning'),Q(1,'What did the villagers fear?','That magic had caused the illness','That the sonata was too long','That a bridge was unsound','The example describes a supernatural explanation.','context'),Q(1,'Which phrase is natural?','accuse someone of sorcery','accuse someone sorceryly for','sorcery to accuse someone ofly','Of introduces the alleged practice.','collocation'),Q(1,'Sorcery entered English through Old French…','sorcerie','solitude','sonata','The English noun came through French.','word-formation')]);
P('sore','Sore comes from Old English sār, “painful, wounded”; it describes physical tenderness, anger, or a painful infected skin place.',[C('sore.s1','健康','My shoulders were sore after carrying boxes up the stairs all afternoon.','整个下午把箱子搬上楼后，我的肩膀酸痛。','a sore muscle/throat; feel sore','形容词，指触碰或使用时疼痛、酸痛。','muscles hurt after exertion.','健康'),C('sore.s2','情绪','He was still sore about being left off the project team.','因为没被选进项目组，他仍然很恼火。','be sore about/at something; a sore loser','口语形容词，指因某事恼火、受了刺激。','exclusion angers him.','情绪'),C('sore.s3','皮肤','The nurse cleaned a sore on the patient’s heel and covered it with a dressing.','护士清理了患者脚跟上的疮口，并用敷料包扎。','a canker sore; a skin sore','可数名词，指皮肤上疼痛或感染的疮、溃疡。','wound is treated.','健康')],M('His shoulders were sore after carrying boxes, but he felt no pain or tenderness at all.','His shoulders were sore and tender after carrying boxes all afternoon.','此处sore表示身体酸痛，与毫无疼痛相矛盾。','meaning'),[Q(1,'Sore shoulders after lifting boxes are…','painful or tender','angry about a team decision','an infected skin patch','Sense 1 is physical pain.','meaning'),Q(2,'Still sore about being left off a team means…','still annoyed or upset','physically covered by a bandage','pleased with the decision','Sense 2 describes irritation or resentment.','context'),Q(3,'A sore on the heel is…','a painful skin wound','a musical voice part','a kind of grain','Sense 3 is a noun for a skin lesion.','meaning'),Q(1,'Which phrase is natural?','sore about the decision','sorely about the decision only','sore at decision aboutly','About can introduce the cause of annoyance.','grammar')]);
P('soreness','Soreness is formed from sore + -ness and means bodily pain or tenderness, or the state of being sore.',C('soreness.s1','健康','Gentle stretching reduced the soreness in her legs after the long hike.','长途徒步后，轻柔拉伸减轻了她腿部的酸痛。','muscle/throat soreness; soreness after exercise','名词，不可数，指身体部位的疼痛或触痛。','stretching eases post-exercise pain.','健康'),M('The soreness in her legs disappeared, but intense pain and tenderness became much worse.','The soreness in her legs eased after she rested and stretched gently.','soreness指疼痛不适，缓解后不应说症状更严重。','meaning'),[Q(1,'Leg soreness after a hike is…','pain or tenderness in the legs','a feeling of pride','a musical performance','That is the bodily sense.','meaning'),Q(1,'What reduced the soreness?','Gentle stretching','Carrying heavier boxes','Making the legs more painful','The example states that stretching eased the discomfort.','context'),Q(1,'Which phrase is natural?','muscle soreness after exercise','muscle sorelyness after exercising','a soreness muscle to after','Soreness is the noun naming the discomfort.','grammar'),Q(1,'Soreness is formed from sore plus…','-ness','-ist','-proof','The suffix forms a noun for a state or quality.','word-formation')]);
P('sorghum','Sorghum comes from Latin sorghum, ultimately an Italian name for the grain; it is a cereal grass cultivated for grain and sometimes sweet syrup.',C('sorghum.s1','农业','Farmers planted sorghum because the crop tolerates heat and needs less water than maize.','农民种植高粱，因为这种作物耐热，而且比玉米需水少。','grow/harvest sorghum; sorghum grain/syrup','名词，不可数，指温暖地区种植、收获籽粒或制糖浆的禾本科作物。','crop tolerates warm dry conditions.','农业'),M('The farmer planted sorghum, a cold-water fish harvested from the harbor.','The farmer planted sorghum, a cereal grass grown for grain.','sorghum是谷类作物，不是鱼。','distinction'),[Q(1,'Sorghum is…','a cereal grass grown for grain','a flat sea fish','a legal profession','That is the source definition.','meaning'),Q(1,'Why did farmers choose the crop?','It tolerates heat and needs relatively little water.','It can only grow underwater.','It is a type of choir music.','The crop is suited to warm regions.','context'),Q(1,'Which phrase is natural?','harvest sorghum grain','harvest a sorghumly grain','sorghum to harvest graining','Sorghum grain is the crop’s edible seed.','collocation'),Q(1,'Sorghum ultimately entered Latin from an Italian…','name for the grain','word for a female singer','term for a legal oath','The word history traces it through Latin to an Italian grain name.','word-formation')]);
P('sorority','Sorority comes from Latin soror, “sister,” with -ity; in American usage it is an organization of women students, often with social activities and a shared house.',C('sorority.s1','教育','The sorority organized a book drive and invited new students to its open house.','这个女大学生联谊会组织了图书募捐，并邀请新生参加开放日。','join/belong to a sorority; a college sorority','名词，指大学女生组织，常举办社交活动，有时共同居住。','student group hosts event.','教育'),M('She joined a sorority, a university organization made up exclusively of male students.','She joined a sorority, a university organization for women students.','sorority是女性学生组织；男性学生组织通常称fraternity。','distinction'),[Q(1,'A sorority is commonly…','an organization of women students','a crop grown for grain','a public legal court','That is the American college sense.','meaning'),Q(1,'What did the sorority organize?','A book drive and open house','A sonar survey under water','A military operation','The example shows social and service activities.','context'),Q(1,'Which phrase is natural?','join a college sorority','join to a college sororityly','a sorority joining of college','Join takes the organization as its direct object.','grammar'),Q(1,'Sorority is related to Latin soror, meaning…','sister','sound','alone','The word is based on the Latin word for sister.','word-formation')]);
P('sorrow','Sorrow is from Old English sorg, “grief, care”; it means deep sadness or an event that causes such sadness.',[C('sorrow.s1','情绪','She felt deep sorrow when the family had to leave their ancestral home.','一家人不得不离开祖宅时，她感到深深的悲伤。','feel/express sorrow; sorrow over/at a loss','名词，指因失去或不幸而产生的深切悲伤。','departure brings grief.','情绪'),C('sorrow.s2','不幸','The closure of the village clinic was a sorrow for residents who depended on it.','村诊所关闭，对依赖它的居民来说是一件令人悲伤的不幸。','a source of sorrow; to someone’s sorrow','名词也可指引起悲伤的不幸事件或事实。','closure causes grief.','事件')],M('She felt sorrow at leaving home, although she was delighted and felt no sadness whatsoever.','She felt sorrow at leaving home because the departure was painful.','sorrow表示悲伤，不能与毫无悲伤的喜悦并用。','meaning'),[Q(1,'Deep sorrow is…','a feeling of profound sadness','a state of financial stability','a grain crop','Sense 1 names an emotion.','meaning'),Q(2,'The clinic closure was a sorrow means it was…','an event that caused sadness','a joyful achievement','a solution to a puzzle','Sense 2 names a sad event or fact.','context'),Q(1,'Which phrase is natural?','feel sorrow over a loss','feel sorrowly a loss over','sorrow to feel of loss','Sorrow can be felt over a loss.','collocation'),Q(1,'Sorrow is from Old English…','sorg','sonus','sophos','The noun descends from Old English sorg.','word-formation')]);
P('sorrowful','Sorrowful is formed from sorrow + -ful; it means feeling or showing deep sadness about an event or loss.',C('sorrowful.s1','情绪','The sorrowful expression on her face showed how much she missed her brother.','她脸上悲伤的神情表明她十分想念哥哥。','a sorrowful face/tone; feel sorrowful about','形容词，表示感到或流露出深切悲伤。','expression reflects grief.','情绪'),M('His sorrowful face showed that he was delighted by the loss and felt no sadness.','His sorrowful face showed that the loss had made him deeply sad.','sorrowful意味着悲伤，不是因失去而欣喜。','meaning'),[Q(1,'A sorrowful expression shows…','deep sadness','financial success','a musical solo','Sorrowful means feeling or showing sorrow.','meaning'),Q(1,'What did her face reveal?','She missed her brother.','She had no emotional response to him.','She was testing a solvent.','The expression communicates grief.','context'),Q(1,'Which phrase is natural?','a sorrowful tone','a sorrowfully tone','a tone sorrowfulness','Sorrowful is an adjective modifying tone.','grammar'),Q(1,'Sorrowful is formed from sorrow plus…','-ful','-less','-ist','The suffix forms an adjective meaning full of sorrow.','word-formation')]);
P('sorry','Sorry is from Old English sārig, “distressed, grieved”; it can express regret, sympathy, disappointment, or an apology/request for repetition or attention.',[C('sorry.s1','道歉','I am sorry that I sent the wrong attachment; I will email the correct file now.','很抱歉我发错了附件；我现在就把正确文件发过去。','be sorry for/about; say sorry; sorry that + clause','形容词，表示因自己做错或造成不便而感到抱歉。','speaker accepts responsibility.','道歉'),C('sorry.s2','同情','I am sorry to hear that your grandmother is ill.','听说你祖母生病了，我很难过，也很同情你。','be sorry to hear; feel sorry for someone','形容词，表示为别人的困境感到难过、同情。','speaker sympathizes with listener.','同情'),C('sorry.s3','遗憾','She was sorry that the garden could not be saved from the flood.','花园没能从洪水中保住，她感到很遗憾。','be sorry that; sorry to see','形容词，表示希望某件令人不快的事本可以不同。','regretful about outcome.','遗憾'),C('sorry.s4','交际','Sorry, could you repeat the address? I did not hear the last number.','不好意思，您能重复一下地址吗？我没听清最后一个号码。','Sorry?; Sorry to interrupt; sorry, but…','口语中作道歉、请求重复或引起注意的表达。','polite request for repetition.','交际')],M('I am sorry for sending the wrong file, and I will not correct it because the mistake was entirely my fault.','I am sorry for sending the wrong file, and I will send the correct one now.','承认失误并致歉时，补发正确文件与道歉相符。','meaning'),[Q(1,'“I am sorry I sent the wrong file” expresses…','regret for the speaker’s mistake','sympathy for another person’s illness','a request to repeat an address','Sense 1 is an apology.','meaning'),Q(2,'“I am sorry to hear she is ill” expresses…','sympathy for her situation','an admission that the speaker sent a file','a question about an address','Sense 2 is sympathy.','context'),Q(3,'“She was sorry the garden was lost” means she…','regretted the unfortunate outcome','asked someone to repeat a number','apologized for planting flowers','Sense 3 expresses regret about what happened.','meaning'),Q(4,'“Sorry, could you repeat that?” is used to…','politely request repetition','state that the listener is guilty','describe a sad song','Sense 4 is a conversational request.','usage')]);
P('sort','Sort came from Old French sorte, from Latin sors, “lot, category”; it means a type or kind, arrange items into groups, or resolve a problem.',[C('sort.s1','分类','What sort of music do you listen to while working?','你工作时听哪种音乐？','what sort/kind of; all sorts of','名词，指具有共同特点的一类或一种。','asks for a category.','分类'),C('sort.s2','整理','Please sort the receipts by date before entering them into the account.','把收据按日期整理后再录入账目。','sort things by/into; sort out files','及物动词，指按类别或顺序整理。','documents arranged chronologically.','整理'),C('sort.s3','处理','The two departments met to sort out the disagreement over delivery dates.','两个部门开会处理交货日期上的分歧。','sort out a problem/dispute; get something sorted','动词短语，指处理并解决问题。','meeting addresses dispute.','处理')],M('She sorted the receipts by date by mixing them randomly into one unorganized pile.','She sorted the receipts by date into an ordered sequence.','按日期分类要求形成有序类别，不是随机混放。','meaning'),[Q(1,'“What sort of music?” asks about…','the type or kind of music','the date it was recorded only','a solution in liquid','Sort sense 1 means type or category.','meaning'),Q(2,'Sort receipts by date means…','arrange them according to date','throw them away without looking','write a sonnet on each one','Sense 2 is arranging into an order.','context'),Q(3,'Sort out a disagreement means…','deal with and resolve it','make it more confusing on purpose','put it in a drawer without discussion','Sense 3 means resolve a problem.','meaning'),Q(1,'Which phrase is natural?','all sorts of questions','all sort question ofly','sorts all a question','Sorts of introduces different kinds.','grammar')]);
P('sought-after','Sought-after combines the past participle sought with after; it describes something desired by many people and therefore in great demand.',C('sought-after.s1','需求','The sought-after apartment attracted dozens of applicants within a day.','这套备受追捧的公寓一天内就吸引了数十名申请者。','a sought-after skill/product; highly sought-after','形容词，指许多人想得到、很受欢迎或需求很高。','many applicants compete for it.','需求'),M('The sought-after course had no applicants and nobody wanted to attend it.','The sought-after course had a long waiting list because many students wanted a place.','sought-after表示很多人渴望得到，不是无人问津。','meaning'),[Q(1,'A sought-after apartment is…','desired by many potential tenants','rejected by everyone','already dissolved in water','The adjective means in great demand.','meaning'),Q(1,'Why did the apartment attract applicants quickly?','It was highly desired.','It was unavailable and unwanted.','It was a type of crop.','High demand explains the many applicants.','context'),Q(1,'Which phrase is natural?','a sought-after qualification','a sought afterly qualification','a sought-for-after qualificationly','Sought-after is the established compound adjective.','grammar'),Q(1,'The phrase is built from sought and…','after','alone','solid','Together they form an adjective meaning in demand.','word-formation')]);
P('soul','Soul comes from Old English sāwol; its deeper Germanic origin is uncertain. It can mean an immortal or inner self, a defining quality, a person counted, or a genre of music.',[C('soul.s1','信仰','The poem asks whether the soul survives after the body dies.','这首诗追问灵魂是否会在肉体死亡后继续存在。','the human soul; body and soul','名词，指被认为能在肉体死亡后延续的非物质部分，也指内心自我。','question concerns life after death.','信仰'),C('soul.s2','特质','The old theatre has a soul that its modern replacement seems to lack.','这座老剧院有一种灵魂般的独特气质，而新建的替代建筑似乎没有。','the soul of a place/work; put one’s soul into','名词，比喻事物最能体现其性格的特质或精髓。','building has distinctive character.','特质'),C('soul.s3','人数','Not a soul was waiting at the bus stop after midnight.','午夜之后，公交站一个人也没有。','not a soul; every living soul','名词，可用来指一个人，尤其用于强调人数。','no person is present.','人数'),C('soul.s4','音乐','The band played soul with a strong gospel influence and a steady rhythm.','乐队演奏了受福音音乐影响、节奏稳定的灵魂乐。','soul music; a soul singer','名词，指根植于非裔美国福音音乐和节奏布鲁斯的流行音乐。','genre draws on gospel and R&B.','音乐')],M('Not a soul was at the bus stop, meaning a large crowd of hundreds was waiting there.','Not a soul was at the bus stop, meaning no person was there.','not a soul强调一个人也没有。','meaning'),[Q(1,'The poem’s soul is the part believed to…','continue after bodily death','make a person’s shoes','produce sound waves','Sense 1 is the spiritual or inner self.','meaning'),Q(2,'The soul of an old theatre is…','its distinctive character or essence','a literal crowd of actors','a bus schedule','Sense 2 is figurative essence.','context'),Q(3,'“Not a soul was waiting” means…','no person was there','everyone was waiting','only the singer was present','Soul can count a person in this expression.','meaning'),Q(4,'Soul music has roots in…','African American gospel and rhythm and blues','sonata and spoken dialogue','sorcery and folk tales','The genre sense names a music style.','meaning')]);
P('sound','Sound has several histories: the audible-noise noun and related verb come through French/Latin sonus; the sense “healthy” comes from Old English gesund. It can mean a noise, produce noise, seem, or be firm/healthy/reasonable.',[C('sound.s1','听觉','A sharp sound came from the engine just before it stopped.','发动机停止前传出一声刺耳的响声。','a loud/sharp sound; hear a sound','名词，指听到的声音或响声。','noise precedes engine failure.','听觉'),C('sound.s2','听觉','The alarm sounded twice when smoke reached the detector.','烟雾触及探测器时，警报响了两次。','sound an alarm; bells sound','动词，指发出声音或使某物响起。','alarm produces a noise.','听觉'),C('sound.s3','判断','Your plan sounds practical, especially because it includes a backup route.','你的计划听起来很实用，尤其是还安排了备用路线。','sound + adjective; sound like + noun','系动词，指听起来似乎、给人某种印象。','judgement based on what was heard.','判断'),C('sound.s4','可靠','The auditor found no errors and judged the accounts financially sound.','审计员没有发现错误，认为账目在财务上稳健可靠。','sound advice/evidence/health; financially sound','形容词，指身体健康、结构完好或基于良好判断而可靠。','accounts are reliable.','可靠'),C('sound.s5','睡眠','After the overnight shift, he slept soundly until noon.','上完夜班后，他酣睡到中午。','sound asleep; sleep soundly','副词用在sound asleep等表达中，表示熟睡或深深地。','sleep is deep.','睡眠')],M('The plan sounds practical, but its only route crosses a bridge that has already collapsed.','The plan sounds practical because it includes a safe backup route.','已知路线无法通行时，计划就不能称为实用可靠。','meaning'),[Q(1,'An engine sound is…','something heard','a financial account','a sleeping person','Sense 1 is an audible noise.','meaning'),Q(2,'The alarm sounded means it…','made a noise','seemed practical','became a solvent','Sense 2 is the verb meaning produce sound.','context'),Q(3,'“The plan sounds practical” means it…','seems practical from what is heard','is physically healthy','is asleep','Sound is a linking verb meaning seem here.','meaning'),Q(4,'Financially sound accounts are…','reliable and in good condition','audible from a distance','deeply asleep','This adjective sense means dependable.','meaning')]);
P('soundly','Soundly is formed from sound + -ly; it commonly means deeply in soundly asleep or decisively and completely, as in a soundly defeated team.',[C('soundly.s1','睡眠','The exhausted infant slept soundly through the thunder and did not wake.','筋疲力尽的婴儿在雷声中熟睡，没有醒来。','sleep soundly; soundly asleep','副词，表示熟睡地、睡得很沉。','thunder does not disturb sleep.','睡眠'),C('soundly.s1','结果','The defending champions were soundly defeated by the younger team.','卫冕冠军被更年轻的队伍彻底击败。','soundly beaten/defeated; soundly reject','副词也表示彻底、明显地，常修饰击败或否决。','large decisive loss.','结果')],M('The champions were soundly defeated, but they won every set by a wide margin.','The champions were soundly defeated and lost every set by a wide margin.','彻底被击败与大比分获胜相矛盾。','meaning'),[Q(1,'Slept soundly means slept…','deeply without waking','lightly while waking every minute','with a loud musical instrument','The adverb means deeply in this sleep phrase.','meaning'),Q(1,'A team soundly defeated its opponent by…','losing decisively','winning every set easily','playing a quiet song','Soundly modifies the decisive loss.','context'),Q(1,'Which phrase is natural?','soundly asleep','soundly sleepness','a soundly defeatness','Soundly commonly modifies asleep.','collocation'),Q(1,'Soundly is formed from sound plus…','-ly','-ity','-proof','The suffix forms an adverb.','word-formation')]);
P('soundproof','Soundproof combines sound + proof; as an adjective it means preventing sound from entering or escaping, and as a verb it means make a room or structure acoustically insulated.',C('soundproof.s1','建筑','The studio has soundproof walls so that traffic noise cannot reach the microphones.','录音室的墙经过隔音处理，交通噪声传不到麦克风。','soundproof walls/room; soundproof a studio','形容词，指隔音的；也可作动词，表示给房间或建筑做隔音处理。','barrier blocks outside noise.','建筑'),M('The soundproof studio let every traffic noise reach the microphones clearly.','The soundproof studio blocked traffic noise from reaching the microphones.','隔音空间应阻止外部噪声进入。','meaning'),[Q(1,'Soundproof walls are designed to…','keep sound from entering or escaping','amplify every outside noise','dissolve the microphones','That is the meaning of soundproof.','meaning'),Q(1,'Why did the studio use soundproof walls?','To keep traffic noise away from microphones','To make the road louder indoors','To create a musical solo','The walls insulate the recording room acoustically.','context'),Q(1,'Which sentence uses soundproof as a verb?','They soundproofed the rehearsal room.','They soundproofly the rehearsal room.','The room is a soundproofingly.','The verb means make a space insulated from sound.','grammar'),Q(1,'Soundproof combines sound with…','proof, meaning resistant to or protected against','-ness, meaning a state','-ist, meaning a person','The compound describes protection from sound.','word-formation')]);
P('soup','Soup came through French soupe, ultimately from a Germanic word for bread soaked in broth; it is a usually hot liquid dish or a thick, confused mixture by comparison.',[C('soup.s1','饮食','The cook simmered vegetable soup until the carrots were soft.','厨师把蔬菜汤慢炖到胡萝卜变软。','a bowl of soup; soup made from vegetables','名词，通常指用肉、鱼或蔬菜烹制的液体菜肴。','vegetables cook in broth.','饮食'),C('soup.s2','比喻','After three teams edited the same spreadsheet, the data became a confusing soup of duplicate entries.','三个团队共同编辑同一张表格后，数据变成了重复条目混杂的一团。','a soup of + things; a thick/confused soup','名词比喻指混乱、混杂或浓稠的一团事物。','duplicates are mixed together.','比喻')],M('The cook served soup, a dry stack of uncooked carrots with no liquid at all.','The cook served soup, a liquid dish made by simmering vegetables in broth.','汤是液体菜肴，不是干燥生蔬菜堆。','meaning'),[Q(1,'Vegetable soup is…','a liquid dish cooked from vegetables','a dry stack of raw vegetables','a bird’s musical call','Sense 1 is a food dish.','meaning'),Q(2,'A confusing soup of data is…','a disorganized mixture of entries','a clear list with no duplicates','a bowl of broth','The second sense is figurative confusion.','context'),Q(1,'Which phrase is natural?','a bowl of tomato soup','a tomato souply bowl','a soup bowl of tomatoing','A bowl of soup is a standard expression.','grammar'),Q(1,'Soup entered English through French and ultimately relates to…','bread soaked in broth','a Greek wise person','a sound wave','The early word family referred to bread served in broth.','word-formation')]);
P('sour','Sour is from Old English sūr, a Germanic adjective; it describes an acidic taste, spoiled food, an unfriendly mood or deteriorating state, and can mean make acidic or worsen.',[C('sour.s1','味觉','The lemon gave the dressing a sharp, sour taste.','柠檬让这份调味汁带有明显的酸味。','sour taste/flavour; taste sour','形容词，指像柠檬或醋那样有酸味。','lemon creates acidic taste.','味觉'),C('sour.s2','食物','The milk smelled sour, so we poured it down the sink.','牛奶闻起来已经馊了，所以我们把它倒进水槽。','go/turn sour; sour milk','形容词，指食物变质后尝起来或闻起来不新鲜。','spoiled milk is discarded.','食物'),C('sour.s3','关系','Relations between the neighbors soured after the dispute over the fence.','围栏纠纷后，邻居之间的关系恶化了。','a sour mood/relationship; relations sour','形容词也指不友好、阴郁，或形势变坏。','dispute damages relations.','关系'),C('sour.s4','变化','Leave the mixture too long and the bacteria will sour it.','如果把混合物放太久，细菌会使它变酸变坏。','sour milk; sour a relationship','动词，指使食物变酸变质，或使关系、情绪恶化。','bacteria change the mixture.','变化')],M('The milk smelled sour and fresh, with no signs of spoilage after sitting unrefrigerated for a week.','The milk smelled sour and spoiled after sitting unrefrigerated for a week.','sour用于食物表示变质，不应同时说毫无腐坏迹象。','meaning'),[Q(1,'A sour lemon dressing tastes…','acidic and sharp','sweet like syrup','bitter from smoke','Sense 1 is the taste.','meaning'),Q(2,'Milk that has gone sour is…','no longer fresh','frozen solid','a musical composition','Sense 2 refers to spoilage.','context'),Q(3,'Relations soured after a dispute means they…','became unfriendly or worse','became more cooperative','turned into a liquid','Sense 3 is figurative deterioration.','meaning'),Q(4,'Bacteria sour a mixture when they…','make it acidic or spoiled','make it soundproof','make it a solo piece','The verb means cause the sour change.','meaning')]);
})();
